window.COPY = {"ca": {"skip": "Ves al contingut", "nav": ["Nivell", "Les etapes", "El programa", "Preu", "El guia", "Preparació", "Preguntes", "Documents"], "menu": "Obre el menú", "close": "Tanca", "pdf": "Fitxa del viatge", "langLabel": "Idioma", "heroLabel": "BOLÍVIA · SERRALADA D’APOLOBAMBA", "heroTitle": "Apolobamba.<em>El camí ens uneix.</em>", "heroText": "Sis jornades a peu entre Pelechuco i Charazani, per camins de pastors i un pas a més de 5.000 m. Grup reduït, guia de muntanya i guia local.", "heroCta": "Descobreix la travessa", "heroSecond": "Veure el programa dia a dia", "heroDate": "Juny de 2027 · millor època: de mitjan juny a finals de juliol", "photoNote": "Paisatge real d’Apolobamba", "facts": [["6", "jornades de marxa"], ["53 km", "de Pelechuco a Charazani"], ["5.032 m", "pas Sunchulli, el punt més alt"], ["11 + 2", "dies de programa i de reserva"]], "storyLabel": "02 / L’EXPERIÈNCIA", "storyTitle": "Caminar lluny.<br>Sentir-nos a prop.", "storyLead": "Hi ha viatges que es mesuren en quilòmetres. Aquest també es mesura en allò que aprenem pel camí.", "storyText": "De Pelechuco a Charazani, la travessa enllaça valls andines, passos alts i paisatges de pastura al peu de les glaceres de l’Apolobamba. És una ruta exigent i poc freqüentada, que recorrem sense presses, amb temps per al coneixement local i la convivència.", "storyCaption": "Des del camí a Charazani", "values": [["Territori viu", "Interpretem el paisatge amb respecte per les comunitats i el seu coneixement."], ["Un grup que camina junt", "Ritme compartit, reagrupaments i consignes clares."], ["Preparació amb criteri", "Guia de muntanya i guia local, amb un programa pensat per aclimatar-se bé."]], "routeLabel": "03 / LES ETAPES", "routeTitle": "Un camí.<br>Sis jornades per viure’l.", "routeIntro": "Cada dia caminem amb llum: sortida a partir de les 07.10 i arribada al campament abans de les 16.40, hora de Bolívia. Tria una jornada per veure’n les dades principals.", "stageLabel": "Jornada", "distance": "Distància", "ascent": "Ascens", "descent": "Descens", "duration": "11 dies / 10 nits / 6 jornades a peu, + 2 dies de reserva", "max": "Punt més alt", "stageFocus": "La clau de la jornada", "routeNote": "53,4 km en total. Distàncies i desnivells són aproximats i els horaris són de planificació: el recorregut encara s’ha de reconèixer sobre el terreny abans d’obrir reserves. Prop d’un terç del camí segueix pistes obertes per la mineria.", "stageNames": ["Pelechuco → Campament 1", "Campament 1 → Hilo Hilo", "Hilo Hilo → Campament 2", "Campament 2 → Incacancha", "Incacancha → Campament 3", "Campament 3 → Charazani"], "stageDescriptions": ["Sortim de Pelechuco i pugem de manera sostinguda fins al primer pas, a 4.706 m, sobretot per la pista minera que el creua. Baixem a la vall del riu Kotani i acampem al fons de la vall. Una jornada per trobar el ritme del grup i veure com respon cadascú a l’altitud.", "Jornada curta i suau, gairebé tota per pista, fins a la comunitat d’Hilo Hilo. Dormim una mica més avall que la nit anterior i dediquem la tarda a descansar, hidratar-nos i preparar el pas alt de l’endemà.", "El dia gran de la travessa. Remuntem la vall fins al pas Sunchulli, a més de 5.000 m i amb les glaceres a prop, i baixem a acampar a la vall de Sunchulli, antiga zona minera.", "Tres passos enllaçats per damunt dels 4.500 m i el llarg descens en ziga-zaga de les Mil Corbes fins a Incacancha, on acampem vora les cascades.", "Curta en distància i intensa en desnivell. Pugem al pas d’Akamani, sota la muntanya sagrada dels kallawayes, passem l’apacheta de Tambillo i baixem al campament.", "Llarg descens cap a les valls habitades: cruïlla de Curva, pont sobre el riu, una última remuntada i arribada a Charazani."], "stageFocusText": ["Més de 1.000 m de pujada sostinguda i primera nit en tenda a 4.168 m.", "Dia de recuperació: caminar poc, beure molt i dormir bé.", "Hora límit per ser al coll: les 14.40. Amb neu dura o gel al pas, la jornada no es fa.", "El descens de les Mil Corbes demana atenció si el terreny és humit o gelat.", "La distància curta enganya: 600 m de pujada concentrada i fatiga acumulada.", "Si a la cruïlla de Curva anem justos de temps, acabem allà i fem l’últim tram en vehicle."], "journeyLabel": "04 / EL PROGRAMA", "journeyTitle": "Onze dies,<br>pas a pas.", "journeyIntro": "Tres dies a La Paz per aclimatar-nos, un de trasllat, sis jornades a peu i un de retorn.", "reserveTitle": "+ 2 dies de reserva", "reserveText": "Els fem servir si cal més aclimatació, si el temps obliga a esperar o si hi ha algun imprevist. Per això cal disposar de 13 dies, més els vols.", "methodLabel": "COM TREBALLEM", "methodTitle": "La preparació es nota<br>a cada pas.", "methodIntro": "La manera de guiar forma part de l’experiència. Preparar, observar, explicar i aprendre per millorar.", "methodSteps": [["Abans de caminar", "Conversa prèvia per valorar experiència i expectatives, reunió de grup i informació clara sobre nivell, material i possibles canvis."], ["Cada matí", "Briefing breu: objectiu del dia, condicions, aigua, punts de decisió i estat del grup."], ["Durant la jornada", "Ritme de grup, reagrupaments i explicacions sobre el paisatge i la cultura en llocs adequats. El dia del pas Sunchulli, la prioritat és caminar."], ["Després del viatge", "Revisió diària amb el grup, enquesta anònima i pla de millora per a la següent edició."]], "respectTitle": "El territori també ens acompanya.", "respectText": "Coneixement local, acords amb les comunitats, respecte pels camins i gestió responsable de residus i aigua. Les visites i les fotografies de persones es fan amb permís.", "prepLabel": "06 / PREPARACIÓ", "prepTitle": "Una bona motxilla.<br>Una bona preparació.", "prepIntro": "Per a persones amb experiència de travessa, capacitat per a jornades llargues i flexibilitat per conviure amb tendes, fred i canvis de programa.", "gearTitle": "La teva llista de material", "gearHint": "Marca el que ja tens preparat. Allò obligatori es revisa a La Paz abans de sortir.", "gearCount": "elements preparats", "reset": "Desmarca-ho tot", "saved": "Les marques es desen només en aquest navegador. No s’envia cap dada.", "gearGroups": [["Obligatori · roba i descans", ["Botes de muntanya ja provades", "Jaqueta i pantalons impermeables", "Jaqueta de plomes o sintètica", "Guants, gorro i braga de coll", "Sac de confort a −10 °C i aïllant"]], ["Obligatori · motxilla de dia", ["Motxilla de 25–35 litres", "Ampolles per a 2–3 litres i tractament d’aigua", "Frontal amb piles o bateria de recanvi", "Ulleres de categoria 3–4 i crema solar", "Passaport, assegurança i medicació personal"]], ["Recomanat", ["Bastons de trekking", "Capes tèrmiques i mitjons de recanvi", "Menjar de reserva per al camí", "Bateria externa", "Farmaciola personal i bossa per als residus"]]], "altitudeTitle": "L’altitud demana escoltar.", "altitudeText": "Estar en bona forma no garanteix adaptar-se bé. Passem cinc nits per sobre dels 4.000 m i creuem un coll a més de 5.000 m. Abans del viatge cal una revisió amb medicina del viatge.", "altitudePoints": ["Avisa el guia de qualsevol malestar.", "Amb símptomes no es puja a dormir més amunt.", "Si el grup ho necessita, s’allarga o es modifica el programa."], "priceLabel": "05 / PREU DE REFERÈNCIA", "priceTitle": "Saber què hi ha<br>darrere del viatge.", "priceNote": "Preu de referència amb reserva anticipada, per a un grup mínim de 8 persones i un màxim de 13. És una estimació del projecte, pendent dels pressupostos reals dels proveïdors locals.", "perPerson": "per persona", "included": "Què inclou", "includeItems": ["Guia de muntanya i guia local", "Trasllats La Paz–Pelechuco i Charazani–La Paz (La Paz–Curva si s’activa el pla C)", "Mules i suport de càrregues", "Àpats i allotjament de tot el programa", "Tendes i material col·lectiu", "Assegurança de viatge i activitat"], "excluded": "Què no inclou", "excludeItems": ["Vols internacionals", "Equip personal: sac, aïllant, roba i botes", "Despeses personals i propines"], "priceDisclaimer": "Les reserves encara no estan obertes. Dates, preu i serveis es confirmaran després del reconeixement del recorregut.", "priceCta": "Veure les condicions", "docsLabel": "08 / DOCUMENTACIÓ", "docsTitle": "Tot el que necessites<br>per preparar el viatge.", "docsIntro": "Documents per llegir amb calma, imprimir o portar al mòbil. El dossier complet te l’enviem personalment.", "docs": [["Fitxa del viatge", "2 pàgines · PDF", "Nivell, requisits, programa dia a dia, punt de trobada, preu, reserva i cancel·lació."], ["Preparació i material", "2 pàgines · PDF", "Salut i altitud, documents, què porten les mules i llista de material per marcar."], ["Pla d’entrenament", "12 setmanes · PDF", "Què fer cada setmana per arribar preparat, amb treball de força i proves de material."], ["Dossier complet del viatge", "PDF · per WhatsApp", "Etapes punt a punt amb mapes i horaris, clima de juny, allotjaments, preparació i condicions. Te l’enviem quan ens escrius."]], "download": "Descarrega", "sourcesLabel": "Fonts amb què hem contrastat la ruta", "sourcesText": "La base del traçat és un registre GPS de 2012, posat al dia amb informació recent: relats i registres de caminants de 2022–2025, programes d’operadors bolivians consultats el 2026 i OpenStreetMap, on es veu que prop d’un terç del camí ja és pista minera. Cap d’aquestes fonts substitueix el reconeixement sobre el terreny.", "sourcesButton": "Consulta les fonts", "sources": [["Track GPS · Gallotrekk (Wikiloc)", "Registre real del recorregut de 2012: traçat, waypoints i temps de cada etapa."], ["Operador · Bolivian Mountain Guides", "Programa Pelechuco–Charazani: campaments a Palca, Sunchulli i Jatunpampa; pas Sunchulli a 5.100 m."], ["Operador · Kaleidoscope Travel", "Camp vora el riu Illo Illo i unes 6 h fins a Sunchulli; final a Curva."], ["Operador · ZigZag Bolivia", "Unes 9 h de Palca a Sunchulli sense nit intermèdia; camp a 4.500 m."], ["2022 · Expedició Colli", "Entrevista a participants d’una travessa de cinc dies pel mateix corredor."], ["2022 · Registre de caminant", "Track publicat a Wikiloc; no acredita el tram final fins a Charazani."], ["2024 · Relat audiovisual", "Vídeo de la travessa Pelechuco–Charazani, publicat l’octubre de 2024."], ["2025 · Accés a Pelechuco", "Relat del viatge en 4×4 fins a Pelechuco."]], "faqLabel": "07 / ABANS DE DECIDIR", "faqTitle": "Preguntes del camí.", "faqs": [["És adequada com a primera travessa?", "No. Està pensada per a senderistes amb experiència en travesses de diversos dies, acostumats a jornades llargues i a dormir en tenda. Abans de reservar fem una conversa per valorar preparació i expectatives."], ["Quants dies necessito?", "El programa dura 11 dies: tres d’aclimatació a La Paz, un de trasllat, sis jornades a peu i un de retorn. Hi afegim dos dies de reserva, de manera que cal disposar de 13 dies, més els vols."], ["Quina és la jornada més exigent?", "La del pas Sunchulli, el dia 7: 11,4 km, uns 1.060 m de pujada, entre 7 i 9 hores i un coll a més de 5.000 m. Per això el dia abans és curt i dormim a Hilo Hilo."], ["On es dorm?", "Hotel a La Paz, allotjament local senzill a Pelechuco i Charazani i cinc nits en tenda, entre 4.000 i 4.700 m. Les nits són fredes, sovint sota zero."], ["Quina és la millor època?", "De mitjan juny a finals de juliol, el cor de l’estació seca. Maig i setembre són possibles però més incerts, i a l’agost hi ha hagut nevades fortes al pas Sunchulli. Proposem la segona quinzena de juny de 2027."], ["He de carregar tot l’equipatge?", "No. El programa preveu mules per a tendes, cuina i equipatge; durant el dia portes una motxilla amb roba d’abric, aigua i menjar."], ["L’aigua és potable?", "No es beu directament. A la zona hi ha mineria d’or, i tractar l’aigua no n’elimina els metalls: l’agafem només de fonts per sobre de les mines o que la comunitat ens confirma, la tractem sempre i en portem de reserva al tram de Sunchulli."], ["Què passa si fa mal temps o algú no es troba bé?", "El guia pot aturar, escurçar o modificar una jornada, i cada jornada té un pla B preparat. Tenim dos dies de reserva, una ruta alternativa completa (el pla C, per Cañisaya i l’Akamani) i, a gairebé tot el recorregut, sortida en vehicle si cal. Amb neu dura o gel als passos, no es creua."], ["Necessito assegurança?", "El preu inclou una assegurança de viatge i activitat que cobreix trekking fins a 5.100 m, rescat i repatriació. Si ja en tens una, revisa-ho amb nosaltres per no duplicar cobertures."], ["El recorregut està revisat sobre el terreny?", "Encara no. El programa parteix d’un track GPS de 2012 i s’ha contrastat amb relats de caminants de 2022–2025, els itineraris d’operadors bolivians i OpenStreetMap, on ja apareixen les pistes mineres. Abans d’obrir reserves cal un reconeixement de passos, campaments, aigua i el pont de l’última jornada."], ["Ja es pot reservar?", "Encara no. Aquesta web presenta un projecte acadèmic de tècnic esportiu (TD2). Juny de 2027 és una proposta de dates; les reserves s’obririen després de validar el recorregut, els serveis, els permisos i les assegurances."]], "endLabel": "EL PRIMER PAS", "endTitle": "Coneix el viatge.<br>Prepara el teu camí.", "endText": "Mira el programa complet i comprova si la proposta encaixa amb la teva experiència.", "footerLine": "Muntanya, territori i camí compartit.", "footerNote": "Projecte acadèmic TD2 · Izan Pimentel Pérez", "privacy": "Privacitat", "terms": "Condicions del projecte", "credits": "Fotografia i cartografia", "privacyText": "Aquesta web no recull reserves ni dades personals. La llengua i les marques de la llista de material es desen només al teu navegador i les pots esborrar amb els controls de la pàgina. Els enllaços externs tenen les seves pròpies condicions.", "termsText": "Andes Wild Trek és un projecte acadèmic de tècnic esportiu (TD2). Dates, preu i serveis són orientatius i no constitueixen una oferta vinculant. Abans d’obrir reserves s’han de validar el recorregut, els proveïdors, els permisos, les assegurances i les condicions de contractació.", "creditIntro": "Fotografies documentals d’Apolobamba i Pelechuco, amb autoria i llicència identificades. La seva data no certifica l’estat actual del recorregut.", "mapNotice": "Els mapes utilitzen dades OpenStreetMap i SRTM i l’estil OpenTopoMap, CC-BY-SA. El traçat principal parteix d’un registre GPS de 2012; les pistes i les rutes alternatives són d’OpenStreetMap.", "dismiss": "Tanca la finestra", "notice": "", "dayWord": "Dia", "night": "On dormim", "schedule": "Horari previst", "scheduleText": "Sortida {0} · arribada {1}", "approx": "aprox.", "stageTabs": ["Campament 1", "Hilo Hilo", "Pas Sunchulli", "Incacancha", "Akamani", "Charazani"], "itinCols": ["Dia", "Jornada", "Què fem", "Nit"], "itinerary": [["1", "Arribada a La Paz", "Recollida a l’aeroport d’El Alto, trasllat a l’hotel i reunió de benvinguda a les 19.00.", "Hotel · 3.650 m"], ["2", "Adaptació a La Paz", "Passeig suau per la ciutat, hidratació i descans.", "Hotel · 3.650 m"], ["3", "Aclimatació i preparació", "Caminada moderada, revisió de material i reunió prèvia.", "Hotel · 3.650 m"], ["4", "La Paz → Pelechuco", "Trasllat en 4×4 pel llac Titicaca i l’altiplà d’Ulla Ulla. Unes 12 hores.", "Allotjament local · 3.660 m"], ["5", "Pelechuco → Campament 1", "9,7 km · +1.047 m · 6–8 h", "Tenda · 4.168 m"], ["6", "Campament 1 → Hilo Hilo", "4,2 km · 2–3 h · tarda de descans", "Tenda · 4.010 m"], ["7", "Hilo Hilo → pas Sunchulli → Campament 2", "11,4 km · +1.062 m · 7–9 h", "Tenda · 4.500–4.700 m"], ["8", "Campament 2 → Incacancha", "8,3 km · −867 m · 5–7 h", "Tenda · 4.060 m"], ["9", "Incacancha → Campament 3", "4,1 km · +602 m · 4–6 h", "Tenda · 4.171 m"], ["10", "Campament 3 → Charazani", "15,8 km · −1.473 m · 8–9 h 30 min", "Allotjament local · 3.195 m"], ["11", "Charazani → La Paz", "Retorn en vehicle (7–8 hores) i comiat.", "Fi del viatge"]], "priceAmount": "2.700", "hubLabel": "EL TREBALL BLOC A BLOC", "hubTitle": "El projecte,<br>bloc a bloc.", "hubIntro": "Els sis blocs del treball, en PDF. Pots obrir-los, descarregar-los o cercar dins del seu contingut.", "hubFull": "Treball complet", "hubChanges": "Canvis i decisions pendents", "hubSearch": "Cerca dins del treball", "hubSearchPh": "Pressupost, permisos, checklist, Sunchulli…", "hubPresent": "Mode exposició", "hubPresentOff": "Surt del mode exposició", "hubCount": "{0} de 6 blocs", "hubPages": "pàgines", "hubMeta": "PDF · català", "hubOpen": "Obre el PDF", "hubDownload": "Descarrega", "hubRead": "Llegeix el text aquí", "hubNav": "Blocs del treball", "igLabel": "INSTAGRAM / MAQUETA ACADÈMICA", "igText": "Sis publicacions de mostra de la campanya de vuit setmanes. És una maqueta del pla de màrqueting; no és un compte real.", "igCta": "Consulta el pla de màrqueting", "igPosts": ["Sis jornades, un sol camí. Presentem la travessa.", "5.032 m: el dia del pas Sunchulli.", "Pelechuco, on comença tot.", "Què porto a la motxilla? La llista, a la web.", "Grup petit: de 8 a 13 persones.", "Tres dies a La Paz abans de caminar."], "igCredit": "Fotografies: Realnif, Raullike i Das Morton · Wikimedia Commons · CC BY-SA 4.0.", "treballNav": "Treball TD2", "condLabel": "CONDICIONS DEL VIATGE", "condTitle": "Les condicions, clares des del principi.", "conds": [["Grup mínim i màxim", "El viatge surt amb un mínim de 8 persones i un màxim de 13. Si no s’arriba al mínim, t’avisem com a mínim 30 dies abans i et retornem el 100 % del que hagis pagat en 14 dies, o et guardem la plaça per a una altra data."], ["Què inclou el preu", "Guia de muntanya i guia local (amb 10–13 persones s’hi afegeix suport local), trasllats en 4×4 del programa, mules, tots els àpats i allotjaments del programa, tendes i material col·lectiu, i assegurança de viatge i activitat amb trekking fins a 5.100 m, rescat i repatriació."], ["Dies de reserva", "Els dos dies de reserva estan inclosos en el preu. Si s’han d’utilitzar, no tenen cost addicional. Si una situació exigís més dies, t’informaríem del nou programa i del cost abans de continuar."], ["Requisits per participar", "Experiència en travesses de diversos dies, conversa prèvia amb el guia, revisió amb medicina del viatge i passaport vigent. Cal disposar de 13 dies, més els vols."], ["Com es reserva", "Quan s’obrin les reserves: conversa prèvia, dossier complet i contracte de viatge combinat. La plaça queda confirmada amb una senyal del 30 % i la resta es paga 45 dies abans de sortir. Preu: 2.700 € fins a 90 dies abans i 2.850 € després. Andes Wild Trek actua com a organitzador del viatge."], ["Canvis durant el viatge", "El guia pot modificar, escurçar o aturar una jornada per seguretat, meteorologia o estat del grup. Cada jornada té un pla B: l’última es pot acabar a Curva amb vehicle i, si cal, s’evacua per les pistes. Aquests canvis no tenen cost addicional."], ["Si s’activa el pla C", "Si abans de sortir el pas Sunchulli no és practicable o la zona minera no ho aconsella, la travessa es fa per Cañisaya i el camí de l’Akamani. El programa comença amb un trasllat de La Paz a Curva i dura nou dies. El preu no canvia: es mantenen guies, mules, àpats, allotjaments i trasllats, i els dos dies que s’estalvien s’afegeixen als de reserva. T’ho expliquem i ho acceptes abans de sortir de La Paz."], ["Cancel·lació per part teva", "Despeses sobre el preu total: 10 % a més de 90 dies, 25 % de 90 a 61, 50 % de 60 a 31, 75 % de 30 a 15 i 100 % a menys de 15 dies o si no et presentes. Pots cedir la plaça a una altra persona que compleixi els requisits. Sense despeses si hi ha circumstàncies inevitables i extraordinàries a destinació. Condicions pendents de validar amb assessoria."], ["Grup privat", "Per a grups de 8 a 13 persones, amb dates a triar dins de la temporada (del 15 de juny al 31 de juliol) i pressupost a mida."]], "condNote": "Les reserves encara no estan obertes. Dates, preu i condicions definitives es confirmaran després del reconeixement del recorregut.", "tw": {"title": "Treball TD2 · Andes Wild Trek · Apolobamba", "nav": ["El viatge", "El treball", "Plans B i C", "Blocs", "Eines", "Avaluació", "Fonts"], "eyebrow": "TREBALL ACADÈMIC · TÈCNIC ESPORTIU EN MITJA MUNTANYA", "h1": "Andes Wild Trek<br>Apolobamba", "lead": "Projecte de creació d’una empresa de guiatge i d’una travessa de sis jornades entre Pelechuco i Charazani, Bolívia.", "meta": "Izan Pimentel Pérez · 24 de novembre de 2026", "full": "Treball complet (PDF)", "word": "Versió editable (Word)", "back": "Veure la web del viatge", "keyLabel": "EL PROJECTE EN QUATRE PUNTS", "keys": [["Empresa", "Agència organitzadora de viatges combinats amb base a Catalunya i operador local a Bolívia."], ["Programa", "11 dies i 2 de reserva: 3 d’aclimatació, 1 de trasllat, 6 jornades a peu i 1 de retorn. Millor època: de mitjan juny a finals de juliol."], ["Pressupost", "2.700 € per persona amb un mínim de 8 i un màxim de 13; marge objectiu del 20%."], ["Següent pas", "Reconeixement de camp, cotitzacions locals i permisos abans de comercialitzar."]], "present": "Presentacions", "presentOff": "Surt del mode exposició", "toolsLabel": "EINES DEL GUIA I ANNEXOS", "toolsTitle": "Per aplicar-lo<br>sobre el terreny.", "tools": [["Formularis operatius", "10 pàgines · PDF", "Checklist diari, enquesta, autoavaluació, informe de millora i expedient d’obertura.", "dossiers/Apolobamba_Formularis_Operatius.pdf"], ["Enquesta del client", "1 pàgina · PDF · ca, es, en, fr", "Enquesta anònima de satisfacció que es lliura en acabar el viatge, en l’idioma del client.", "dossiers/Enquesta_Satisfaccio_CA.pdf"], ["Atles cartogràfic", "11 làmines · PDF A3", "Mapa general amb els plans B i C, les sis jornades i les quatre etapes del pla C, amb perfil, punts de pas, rutes d’evacuació i GPX.", "dossiers/Apolobamba_Atles_Cartografic_A3.pdf"], ["Flyer amb QR", "Imatge · JPG", "Peça del pla de màrqueting amb fotografia real; el QR obre la web del viatge.", "assets/flyer.jpg"], ["App del guia", "Mòbil · sense cobertura", "Horari i llum en temps real, GPS sobre el traçat, hores límit i decisions, mapa sense cobertura, plans B i C, meteo per punts, SOS amb coordenades, llistes i GPX.", "guia/"], ["Dossier complet del client", "15 pàgines · PDF", "Document que s’envia al client quan contacta: etapes punt a punt, mapes, clima i condicions.", "dossiers/client/Dossier_Viatge_CA.pdf"]], "open": "Obre", "sourcesLabel": "FONTS", "sourcesTitle": "Contrast de la ruta", "mapLabel": "MAPA DEL TREBALL", "mapTitle": "Com encaixen les peces.", "map": [["Empresa i mercat", [["Entorn laboral", "Model d’agència, públic i DAFO", "empresa"], ["Normativa", "Titulació, contracte i assegurances", "normativa"], ["Màrqueting", "Missatge, campanya i flyer", "marketing"]]], ["Producte", [["Programa", "11 dies + 2, sis jornades i aclimatació", "empresa"], ["Pressupost", "2.700 € amb un mínim de 8", "empresa"], ["Fitxa del client", "Què rep qui s’hi apunta", "client"]]], ["Operació", [["Metodologia", "Conducció, dinàmiques i avaluació", "metodologia"], ["Fitxa del guia", "Horaris, punts de decisió i mapes", "guia"], ["Formularis", "Checklist, enquesta i expedient", "eines"]]]], "mapBase": "Tot el treball descansa en dos límits: les competències del TD2 al pas Sunchulli i el reconeixement de camp previ a la venda.", "planLabel": "TEMPORADA, PLANS B I PLA C", "planHeading": "Quan anar-hi<br>i què fem si no es pot passar.", "planIntro": "Revisió del 17/11/2026 amb fonts de muntanyencs, operadors, l’ABC i OpenStreetMap. Cada jornada té plans B i vies d’evacuació, i el pla C és una ruta completa per l’Akamani.", "planBTitle": "Plans B per jornada", "planCTitle": "Fitxes tècniques del pla C", "roadsNote": "Consultat el", "colsC": ["Etapa", "Dia", "Km", "Desnivell", "Màx.", "Durada", "Horari", "Nit"], "gpxB": "Descarrega el pla B del dia", "gpxC": "GPX del pla C", "gpxMain": "GPX de la ruta principal", "avalLabel": "INSTRUMENTS D’AVALUACIÓ", "avalTitle": "Avaluar de debò,<br>no només sobre el paper.", "avalIntro": "L’enquesta del client, el checklist diari i l’autoavaluació del guia de l’Annex A, convertits en eines que es poden fer servir. L’enquesta és un formulari anònim en quatre idiomes; el checklist i l’autoavaluació funcionen dins de l’app del guia, sense cobertura, i s’exporten en CSV o PDF.", "avalQr": "Escaneja per obrir l’enquesta", "aval": [["Enquesta del client en línia", "Formulari de Google · anònim · ca, es, en, fr", "El client tria l’idioma i respon des del mòbil en acabar el viatge (uns 3 minuts). No es demana nom ni correu; les respostes van a un full de càlcul del responsable.", "https://docs.google.com/forms/d/e/1FAIpQLScnXaBFRML574r8K5PI5J7VZYa5B6C28ZPedfOIt_a5luli2g/viewform"], ["Checklist diari del guia", "App del guia · sense cobertura", "Dotze comprovacions abans de sortir (Sí / No / NA), decisió d’inici i registre de la jornada. Es desa al mòbil i s’exporta en CSV o PDF.", "guia/?aval=check"], ["Autoavaluació del guia", "App del guia · sense cobertura", "Deu aspectes valorats d’1 a 5 amb un fet observable, mitjana i tancament amb l’acció prioritària. Dins de les 72 hores posteriors al servei.", "guia/?aval=auto"], ["QR de l’enquesta", "Imatge · SVG", "Per imprimir a la libreta de ruta o ensenyar des de l’app l’últim dia, perquè cada client l’obri amb el seu mòbil.", "assets/enquesta-qr.svg"]]}, "stageDossier": "Els punts de pas, els mapes i els horaris detallats de cada jornada són al dossier complet, que t’enviem quan ens escrius.", "docRequest": "Demana’l", "seasonLabel": "QUAN ANAR-HI", "planTitle": "Si el camí no deixa passar", "planText": "Cada jornada té un pla B preparat i hi ha una ruta alternativa completa. Si cal canviar, el guia ho decideix pensant en la seguretat del grup.", "planItems": [["Pas Sunchulli (5.032 m)", "Hi ha hora límit: les 14.40. Si no hi arribem a temps, si hi ha neu dura o gel o si el temps és dolent, tornem a Hilo Hilo i fem servir un dia de reserva."], ["Baixada de les Mil Corbes", "Amb neu, gel o poca visibilitat no hi entrem. Hi ha una baixada alternativa més llarga i menys dreta, o podem dormir a la comunitat de Quellwa Cota."], ["Final de la travessa", "Si anem justos de temps, acabem a Curva i seguim en vehicle fins a Charazani."], ["Pla C · per l’Akamani", "Si el pas Sunchulli no és practicable o la zona minera no ho aconsella, fem la travessa per Cañisaya i el camí de l’Akamani fins a Charazani: quatre jornades, 35 km i un màxim de 4.661 m."], ["Pistes i evacuació", "Prop d’un terç del camí va per pistes mineres. A canvi, a gairebé tot el recorregut un vehicle pot arribar si cal evacuar algú."]], "levelLabel": "01 / NIVELL I REQUISITS", "levelTitle": "És per a tu?<br>Mira-ho abans.", "levelIntro": "Quatre indicadors per saber, d’un cop d’ull, què demana la travessa. La dificultat tècnica és baixa: el que la fa exigent és la durada, l’altitud i l’aïllament.", "levels": [["Exigència física", 3, "Alta", "Jornades de fins a 9 h 30, sis dies seguits, i gairebé 1.500 m de baixada l’últim dia."], ["Dificultat tècnica", 1, "Baixa", "Sender i pista, sense grimpada. No cal grampons ni piolet: amb neu dura o gel, no es creua."], ["Altitud", 4, "Molt alta", "Cinc nits per sobre dels 4.000 m i un pas a 5.032 m. Cal aclimatació i no tothom s’hi adapta igual."], ["Aïllament", 3, "Alt", "Sense cobertura de mòbil. Una evacuació pot trigar hores o un dia, per pista o a peu."]], "reqTitle": "Requisits per participar", "reqs": ["Haver fet com a mínim una travessa de 3 dies o més amb motxilla i nits fora de casa.", "Poder caminar 8–9 hores amb uns 1.000 m de desnivell i repetir-ho l’endemà.", "Revisió amb un centre de medicina del viatge i cap contraindicació per a l’altitud.", "Passaport vigent i 13 dies lliures, més els vols.", "Acceptar les decisions del guia sobre ritme, retirades i plans alternatius."], "meetTitle": "Punt de trobada", "meetText": "Dia 1, aeroport internacional d’El Alto (La Paz, LPB): et recollim quan arriba el teu vol i et portem a l’hotel. Reunió de benvinguda a les 19.00 a l’hotel. El servei acaba el dia 11 a la tarda, en arribar a La Paz.", "earlyLabel": "Reserva anticipada · fins a 90 dies abans", "stdLabel": "A menys de 90 dies de la sortida", "priceStd": "2.850", "guarantee": ["Garantia de sortida", "Si no s’arriba a 8 persones, t’avisem com a mínim 30 dies abans i et retornem el 100 % del que hagis pagat en 14 dies, o et guardem la plaça per a una altra data, com prefereixis."], "extrasTitle": "Suplements opcionals", "extras": [["Habitació individual (hotels de La Paz, Pelechuco i Charazani)", "Preu a confirmar"], ["Tenda individual", "Preu a confirmar"], ["Lloguer de sac de dormir de −10 °C", "Preu a confirmar"], ["Nits a La Paz després del dia 11 si no s’utilitzen els dies de reserva", "A càrrec teu; t’ajudem a reservar"]], "bookTitle": "Com es reserva", "bookSteps": [["Escriu-nos", "Per WhatsApp, amb la data que t’interessa i la teva experiència."], ["Conversa prèvia", "Parlem de la teva experiència, salut i expectatives per veure si la travessa és per a tu."], ["Dossier i contracte", "Et passem el dossier complet i el contracte de viatge combinat."], ["Senyal i confirmació", "Pagues la senyal del 30 % i la plaça queda confirmada. La resta, 45 dies abans de sortir."]], "cancelTitle": "Si has d’anul·lar", "cancelCols": ["Quan anul·les", "Despeses sobre el preu total"], "cancelRows": [["Més de 90 dies abans", "10 %"], ["De 90 a 61 dies", "25 %"], ["De 60 a 31 dies", "50 %"], ["De 30 a 15 dies", "75 %"], ["Menys de 15 dies o no presentar-se", "100 %"]], "cancelNotes": ["Pots cedir la plaça a una altra persona que compleixi els requisits; només pagues les despeses del canvi.", "Sense despeses si a destinació hi ha circumstàncies inevitables i extraordinàries que impedeixin el viatge.", "Et recomanem una assegurança d’anul·lació, que no està inclosa."], "privateTitle": "Grup privat", "privateText": "Si sou un grup de 8 a 13 persones, podeu triar les dates dins de la temporada (del 15 de juny al 31 de juliol). Us fem un pressupost a mida.", "gearOrgTitle": "Ho porta l’organització", "gearOrg": ["Tendes, cuina i tots els àpats de la travessa", "Mules per a l’equipatge", "Farmaciola de grup i oxímetre", "Comunicador per satèl·lit", "Material de seguretat del grup"], "levelWord": "Nivell", "foldMore": "Mostra’n més", "foldLess": "Mostra’n menys", "stagePhotoAlt": ["Carrer empedrat de Pelechuco, on comença la travessa", "Llama i cims nevats a l’Àrea Natural de Maneig Integrat Apolobamba", "Carena rocallosa i neu a l’alta muntanya de l’Apolobamba", "Carena i valls amb llacunes a l’Àrea Natural de Maneig Integrat Apolobamba", "La serralada d’Apolobamba vista des del camí a Charazani", "La vall entre Charazani i Curva, l’última jornada"], "stagePhotoNote": "Foto de referència del paisatge de la zona: no és necessàriament el punt exacte de la jornada.", "planShort": [["B", "Un pla B per a cada jornada", "Si el temps, el terreny o el grup no acompanyen, tornem enrere, escurcem la jornada o seguim en vehicle."], ["+2", "Dos dies de reserva", "Inclosos en el preu, per esperar millor temps o aclimatar-nos més."], ["C", "Una ruta alternativa completa", "Si el pas principal no és practicable, fem la travessa per un altre camí fins a Charazani."]], "seasonShort": [["Juny i juliol", "El cor de l’estació seca: temps més estable i nits fredes."], ["Maig i setembre", "Possibles, però amb més pluges o tempestes de tarda."], ["Agost", "Pot nevar fort als passos: només amb previsió estable."], ["De desembre a abril", "Estació de pluges: no hi anem."]]}, "es": {"skip": "Ir al contenido", "nav": ["Nivel", "Las etapas", "El programa", "Precio", "El guía", "Preparación", "Preguntas", "Documentos"], "menu": "Abrir menú", "close": "Cerrar", "pdf": "Ficha del viaje", "langLabel": "Idioma", "heroLabel": "BOLIVIA · CORDILLERA DE APOLOBAMBA", "heroTitle": "Apolobamba.<em>El camino nos une.</em>", "heroText": "Seis jornadas a pie entre Pelechuco y Charazani, por caminos de pastores y un paso a más de 5.000 m. Grupo reducido, guía de montaña y guía local.", "heroCta": "Descubre la travesía", "heroSecond": "Ver el programa día a día", "heroDate": "Junio de 2027 · mejor época: de mediados de junio a finales de julio", "photoNote": "Paisaje real de Apolobamba", "facts": [["6", "jornadas de marcha"], ["53 km", "de Pelechuco a Charazani"], ["5.032 m", "paso Sunchulli, el punto más alto"], ["11 + 2", "días de programa y de reserva"]], "storyLabel": "02 / LA EXPERIENCIA", "storyTitle": "Caminar lejos.<br>Sentirnos cerca.", "storyLead": "Hay viajes que se miden en kilómetros. Este también se mide en lo que aprendemos por el camino.", "storyText": "De Pelechuco a Charazani, la travesía enlaza valles andinos, pasos altos y paisajes de pastoreo al pie de los glaciares de Apolobamba. Es una ruta exigente y poco frecuentada, que recorremos sin prisas, con tiempo para el conocimiento local y la convivencia.", "storyCaption": "Desde el camino a Charazani", "values": [["Territorio vivo", "Interpretamos el paisaje con respeto por las comunidades y su conocimiento."], ["Un grupo que camina junto", "Ritmo compartido, reagrupamientos e instrucciones claras."], ["Preparación con criterio", "Guía de montaña y guía local, con un programa pensado para aclimatarse bien."]], "routeLabel": "03 / LAS ETAPAS", "routeTitle": "Un camino.<br>Seis jornadas para vivirlo.", "routeIntro": "Cada día caminamos con luz: salida a partir de las 07:10 y llegada al campamento antes de las 16:40, hora de Bolivia. Elige una jornada para ver sus datos principales.", "stageLabel": "Jornada", "distance": "Distancia", "ascent": "Ascenso", "descent": "Descenso", "duration": "11 días / 10 noches / 6 jornadas a pie, + 2 días de reserva", "max": "Punto más alto", "stageFocus": "La clave de la jornada", "routeNote": "53,4 km en total. Distancias y desniveles son aproximados y los horarios son de planificación: el recorrido todavía debe reconocerse sobre el terreno antes de abrir reservas. Cerca de un tercio del camino sigue pistas abiertas por la minería.", "stageNames": ["Pelechuco → Campamento 1", "Campamento 1 → Hilo Hilo", "Hilo Hilo → Campamento 2", "Campamento 2 → Incacancha", "Incacancha → Campamento 3", "Campamento 3 → Charazani"], "stageDescriptions": ["Salimos de Pelechuco y subimos de forma sostenida hasta el primer paso, a 4.706 m, sobre todo por la pista minera que lo cruza. Bajamos al valle del río Kotani y acampamos en el fondo del valle. Una jornada para encontrar el ritmo del grupo y ver cómo responde cada persona a la altitud.", "Jornada corta y suave, casi toda por pista, hasta la comunidad de Hilo Hilo. Dormimos algo más abajo que la noche anterior y dedicamos la tarde a descansar, hidratarnos y preparar el paso alto del día siguiente.", "El gran día de la travesía. Remontamos el valle hasta el paso Sunchulli, a más de 5.000 m y con los glaciares cerca, y bajamos a acampar al valle de Sunchulli, antigua zona minera.", "Tres pasos enlazados por encima de los 4.500 m y el largo descenso en zigzag de las Mil Curvas hasta Incacancha, donde acampamos junto a las cascadas.", "Corta en distancia e intensa en desnivel. Subimos al paso de Akamani, bajo la montaña sagrada de los kallawayas, pasamos la apacheta de Tambillo y bajamos al campamento.", "Largo descenso hacia los valles habitados: cruce de Curva, puente sobre el río, una última remontada y llegada a Charazani."], "stageFocusText": ["Más de 1.000 m de subida sostenida y primera noche en tienda a 4.168 m.", "Día de recuperación: caminar poco, beber mucho y dormir bien.", "Hora límite para estar en el collado: las 14:40. Con nieve dura o hielo en el paso, la jornada no se hace.", "El descenso de las Mil Curvas pide atención si el terreno está húmedo o helado.", "La distancia corta engaña: 600 m de subida concentrada y fatiga acumulada.", "Si en el cruce de Curva vamos justos de tiempo, terminamos allí y hacemos el último tramo en vehículo."], "journeyLabel": "04 / EL PROGRAMA", "journeyTitle": "Once días,<br>paso a paso.", "journeyIntro": "Tres días en La Paz para aclimatarnos, uno de traslado, seis jornadas a pie y uno de regreso.", "reserveTitle": "+ 2 días de reserva", "reserveText": "Los usamos si hace falta más aclimatación, si el tiempo obliga a esperar o si surge algún imprevisto. Por eso hay que disponer de 13 días, más los vuelos.", "methodLabel": "CÓMO TRABAJAMOS", "methodTitle": "La preparación se nota<br>en cada paso.", "methodIntro": "La forma de guiar forma parte de la experiencia. Preparar, observar, explicar y aprender para mejorar.", "methodSteps": [["Antes de caminar", "Conversación previa para valorar experiencia y expectativas, reunión de grupo e información clara sobre nivel, material y posibles cambios."], ["Cada mañana", "Briefing breve: objetivo del día, condiciones, agua, puntos de decisión y estado del grupo."], ["Durante la jornada", "Ritmo de grupo, reagrupamientos y explicaciones sobre el paisaje y la cultura en lugares adecuados. El día del paso Sunchulli, la prioridad es caminar."], ["Después del viaje", "Revisión diaria con el grupo, encuesta anónima y plan de mejora para la siguiente edición."]], "respectTitle": "El territorio también nos acompaña.", "respectText": "Conocimiento local, acuerdos con las comunidades, respeto por los caminos y gestión responsable de residuos y agua. Las visitas y fotografías de personas se hacen con permiso.", "prepLabel": "06 / PREPARACIÓN", "prepTitle": "Una buena mochila.<br>Una buena preparación.", "prepIntro": "Para personas con experiencia de travesía, capacidad para jornadas largas y flexibilidad para convivir con tiendas, frío y cambios de programa.", "gearTitle": "Tu lista de material", "gearHint": "Marca lo que ya tienes preparado. Lo obligatorio se revisa en La Paz antes de salir.", "gearCount": "elementos preparados", "reset": "Desmarcar todo", "saved": "Las marcas se guardan solo en este navegador. No se envía ningún dato.", "gearGroups": [["Obligatorio · ropa y descanso", ["Botas de montaña ya probadas", "Chaqueta y pantalones impermeables", "Chaqueta de plumas o sintética", "Guantes, gorro y braga de cuello", "Saco de confort a −10 °C y aislante"]], ["Obligatorio · mochila de día", ["Mochila de 25–35 litros", "Botellas para 2–3 litros y tratamiento de agua", "Frontal con pilas o batería de recambio", "Gafas de categoría 3–4 y crema solar", "Pasaporte, seguro y medicación personal"]], ["Recomendado", ["Bastones de trekking", "Capas térmicas y calcetines de recambio", "Comida de reserva para el camino", "Batería externa", "Botiquín personal y bolsa para los residuos"]]], "altitudeTitle": "La altitud pide escuchar.", "altitudeText": "Estar en buena forma no garantiza adaptarse bien. Pasamos cinco noches por encima de los 4.000 m y cruzamos un collado a más de 5.000 m. Antes del viaje hace falta una revisión con medicina del viajero.", "altitudePoints": ["Avisa al guía de cualquier malestar.", "Con síntomas no se sube a dormir más alto.", "Si el grupo lo necesita, se amplía o modifica el programa."], "priceLabel": "05 / PRECIO DE REFERENCIA", "priceTitle": "Saber qué hay<br>detrás del viaje.", "priceNote": "Precio de referencia con reserva anticipada, para un grupo mínimo de 8 personas y un máximo de 13. Es una estimación del proyecto, pendiente de los presupuestos reales de los proveedores locales.", "perPerson": "por persona", "included": "Qué incluye", "includeItems": ["Guía de montaña y guía local", "Traslados La Paz–Pelechuco y Charazani–La Paz (La Paz–Curva si se activa el plan C)", "Mulas y apoyo de cargas", "Comidas y alojamiento de todo el programa", "Tiendas y material colectivo", "Seguro de viaje y actividad"], "excluded": "Qué no incluye", "excludeItems": ["Vuelos internacionales", "Equipo personal: saco, aislante, ropa y botas", "Gastos personales y propinas"], "priceDisclaimer": "Las reservas todavía no están abiertas. Fechas, precio y servicios se confirmarán tras el reconocimiento del recorrido.", "priceCta": "Ver las condiciones", "docsLabel": "08 / DOCUMENTACIÓN", "docsTitle": "Todo lo que necesitas<br>para preparar el viaje.", "docsIntro": "Documentos para leer con calma, imprimir o llevar en el móvil. El dossier completo te lo enviamos personalmente.", "docs": [["Ficha del viaje", "2 páginas · PDF", "Nivel, requisitos, programa día a día, punto de encuentro, precio, reserva y cancelación."], ["Preparación y material", "2 páginas · PDF", "Salud y altitud, documentos, qué llevan las mulas y lista de material para marcar."], ["Plan de entrenamiento", "12 semanas · PDF", "Qué hacer cada semana para llegar preparado, con trabajo de fuerza y pruebas de material."], ["Dossier completo del viaje", "PDF · por WhatsApp", "Etapas punto a punto con mapas y horarios, clima de junio, alojamientos, preparación y condiciones. Te lo enviamos cuando nos escribes."]], "download": "Descargar", "sourcesLabel": "Fuentes con las que hemos contrastado la ruta", "sourcesText": "La base del trazado es un registro GPS de 2012, puesto al día con información reciente: relatos y registros de caminantes de 2022–2025, programas de operadores bolivianos consultados en 2026 y OpenStreetMap, donde se ve que cerca de un tercio del camino ya es pista minera. Ninguna de estas fuentes sustituye el reconocimiento sobre el terreno.", "sourcesButton": "Consulta las fuentes", "sources": [["Track GPS · Gallotrekk (Wikiloc)", "Registro real del recorrido de 2012: trazado, waypoints y tiempos de cada etapa."], ["Operador · Bolivian Mountain Guides", "Programa Pelechuco–Charazani: campamentos en Palca, Sunchulli y Jatunpampa; paso Sunchulli a 5.100 m."], ["Operador · Kaleidoscope Travel", "Campamento junto al río Illo Illo y unas 6 h hasta Sunchulli; final en Curva."], ["Operador · ZigZag Bolivia", "Unas 9 h de Palca a Sunchulli sin noche intermedia; campamento a 4.500 m."], ["2022 · Expedición Colli", "Entrevista a participantes de una travesía de cinco días por el mismo corredor."], ["2022 · Registro de caminante", "Track publicado en Wikiloc; no acredita el tramo final hasta Charazani."], ["2024 · Relato audiovisual", "Vídeo de la travesía Pelechuco–Charazani, publicado en octubre de 2024."], ["2025 · Acceso a Pelechuco", "Relato del viaje en 4×4 hasta Pelechuco."]], "faqLabel": "07 / ANTES DE DECIDIR", "faqTitle": "Preguntas del camino.", "faqs": [["¿Es adecuada como primera travesía?", "No. Está pensada para senderistas con experiencia en travesías de varios días, acostumbrados a jornadas largas y a dormir en tienda. Antes de reservar hacemos una conversación para valorar preparación y expectativas."], ["¿Cuántos días necesito?", "El programa dura 11 días: tres de aclimatación en La Paz, uno de traslado, seis jornadas a pie y uno de regreso. Añadimos dos días de reserva, así que hay que disponer de 13 días, más los vuelos."], ["¿Cuál es la jornada más exigente?", "La del paso Sunchulli, el día 7: 11,4 km, unos 1.060 m de subida, entre 7 y 9 horas y un collado a más de 5.000 m. Por eso el día anterior es corto y dormimos en Hilo Hilo."], ["¿Dónde se duerme?", "Hotel en La Paz, alojamiento local sencillo en Pelechuco y Charazani y cinco noches en tienda, entre 4.000 y 4.700 m. Las noches son frías, a menudo bajo cero."], ["¿Cuál es la mejor época?", "De mediados de junio a finales de julio, el corazón de la estación seca. Mayo y septiembre son posibles pero más inciertos, y en agosto ha habido nevadas fuertes en el paso Sunchulli. Proponemos la segunda quincena de junio de 2027."], ["¿Tengo que cargar todo el equipaje?", "No. El programa prevé mulas para tiendas, cocina y equipaje; durante el día llevas una mochila con ropa de abrigo, agua y comida."], ["¿El agua es potable?", "No se bebe directamente. En la zona hay minería de oro, y tratar el agua no elimina los metales: la cogemos solo de fuentes por encima de las minas o que la comunidad nos confirma, la tratamos siempre y llevamos de reserva en el tramo de Sunchulli."], ["¿Qué pasa si hace mal tiempo o alguien no se encuentra bien?", "El guía puede detener, acortar o modificar una jornada, y cada jornada tiene un plan B preparado. Tenemos dos días de reserva, una ruta alternativa completa (el plan C, por Cañisaya y el Akamani) y, en casi todo el recorrido, salida en vehículo si hace falta. Con nieve dura o hielo en los pasos, no se cruza."], ["¿Necesito seguro?", "El precio incluye un seguro de viaje y actividad que cubre trekking hasta 5.100 m, rescate y repatriación. Si ya tienes uno, revísalo con nosotros para no duplicar coberturas."], ["¿El recorrido está revisado sobre el terreno?", "Todavía no. El programa parte de un track GPS de 2012 y se ha contrastado con relatos de caminantes de 2022–2025, los itinerarios de operadores bolivianos y OpenStreetMap, donde ya aparecen las pistas mineras. Antes de abrir reservas hace falta un reconocimiento de pasos, campamentos, agua y el puente de la última jornada."], ["¿Ya se puede reservar?", "Todavía no. Esta web presenta un proyecto académico de técnico deportivo (TD2). Junio de 2027 es una propuesta de fechas; las reservas se abrirían después de validar el recorrido, los servicios, los permisos y los seguros."]], "endLabel": "EL PRIMER PASO", "endTitle": "Conoce el viaje.<br>Prepara tu camino.", "endText": "Mira el programa completo y comprueba si la propuesta encaja con tu experiencia.", "footerLine": "Montaña, territorio y camino compartido.", "footerNote": "Proyecto académico TD2 · Izan Pimentel Pérez", "privacy": "Privacidad", "terms": "Condiciones del proyecto", "credits": "Fotografía y cartografía", "privacyText": "Esta web no recoge reservas ni datos personales. El idioma y las marcas de la lista de material se guardan solo en tu navegador y puedes borrarlas con los controles de la página. Los enlaces externos tienen sus propias condiciones.", "termsText": "Andes Wild Trek es un proyecto académico de técnico deportivo (TD2). Fechas, precio y servicios son orientativos y no constituyen una oferta vinculante. Antes de abrir reservas deben validarse el recorrido, los proveedores, los permisos, los seguros y las condiciones de contratación.", "creditIntro": "Fotografías documentales de Apolobamba y Pelechuco, con autoría y licencia identificadas. Su fecha no certifica el estado actual del recorrido.", "mapNotice": "Los mapas utilizan datos OpenStreetMap y SRTM y el estilo OpenTopoMap, CC-BY-SA. El trazado principal parte de un registro GPS de 2012; las pistas y las rutas alternativas son de OpenStreetMap.", "dismiss": "Cerrar la ventana", "notice": "", "dayWord": "Día", "night": "Dónde dormimos", "schedule": "Horario previsto", "scheduleText": "Salida {0} · llegada {1}", "approx": "aprox.", "stageTabs": ["Campamento 1", "Hilo Hilo", "Paso Sunchulli", "Incacancha", "Akamani", "Charazani"], "itinCols": ["Día", "Jornada", "Qué hacemos", "Noche"], "itinerary": [["1", "Llegada a La Paz", "Recogida en el aeropuerto de El Alto, traslado al hotel y reunión de bienvenida a las 19:00.", "Hotel · 3.650 m"], ["2", "Adaptación en La Paz", "Paseo suave por la ciudad, hidratación y descanso.", "Hotel · 3.650 m"], ["3", "Aclimatación y preparación", "Caminata moderada, revisión de material y reunión previa.", "Hotel · 3.650 m"], ["4", "La Paz → Pelechuco", "Traslado en 4×4 por el lago Titicaca y el altiplano de Ulla Ulla. Unas 12 horas.", "Alojamiento local · 3.660 m"], ["5", "Pelechuco → Campamento 1", "9,7 km · +1.047 m · 6–8 h", "Tienda · 4.168 m"], ["6", "Campamento 1 → Hilo Hilo", "4,2 km · 2–3 h · tarde de descanso", "Tienda · 4.010 m"], ["7", "Hilo Hilo → paso Sunchulli → Campamento 2", "11,4 km · +1.062 m · 7–9 h", "Tienda · 4.500–4.700 m"], ["8", "Campamento 2 → Incacancha", "8,3 km · −867 m · 5–7 h", "Tienda · 4.060 m"], ["9", "Incacancha → Campamento 3", "4,1 km · +602 m · 4–6 h", "Tienda · 4.171 m"], ["10", "Campamento 3 → Charazani", "15,8 km · −1.473 m · 8–9 h 30 min", "Alojamiento local · 3.195 m"], ["11", "Charazani → La Paz", "Regreso en vehículo (7–8 horas) y despedida.", "Fin del viaje"]], "priceAmount": "2.700", "hubLabel": "EL TRABAJO BLOQUE A BLOQUE", "hubTitle": "El proyecto,<br>bloque a bloque.", "hubIntro": "Los seis bloques del trabajo, en PDF y en catalán. Puedes abrirlos, descargarlos o buscar dentro de su contenido.", "hubFull": "Trabajo completo", "hubChanges": "Cambios y decisiones pendientes", "hubSearch": "Busca dentro del trabajo", "hubSearchPh": "Presupuesto, permisos, checklist, Sunchulli…", "hubPresent": "Modo exposición", "hubPresentOff": "Salir del modo exposición", "hubCount": "{0} de 6 bloques", "hubPages": "páginas", "hubMeta": "PDF · en catalán", "hubOpen": "Abrir el PDF", "hubDownload": "Descargar", "hubRead": "Lee el texto aquí (en catalán)", "hubNav": "Bloques del trabajo", "igLabel": "INSTAGRAM / MAQUETA ACADÉMICA", "igText": "Seis publicaciones de muestra de la campaña de ocho semanas. Es una maqueta del plan de marketing; no es una cuenta real.", "igCta": "Consulta el plan de marketing", "igPosts": ["Seis jornadas, un solo camino. Presentamos la travesía.", "5.032 m: el día del paso Sunchulli.", "Pelechuco, donde empieza todo.", "¿Qué llevo en la mochila? La lista, en la web.", "Grupo pequeño: de 8 a 13 personas.", "Tres días en La Paz antes de caminar."], "igCredit": "Fotografías: Realnif, Raullike y Das Morton · Wikimedia Commons · CC BY-SA 4.0.", "treballNav": "Trabajo TD2", "condLabel": "CONDICIONES DEL VIAJE", "condTitle": "Las condiciones, claras desde el principio.", "conds": [["Grupo mínimo y máximo", "El viaje sale con un mínimo de 8 personas y un máximo de 13. Si no se llega al mínimo, te avisamos como mínimo 30 días antes y te devolvemos el 100 % de lo que hayas pagado en 14 días, o te guardamos la plaza para otra fecha."], ["Qué incluye el precio", "Guía de montaña y guía local (con 10–13 personas se añade apoyo local), traslados en 4×4 del programa, mulas, todas las comidas y alojamientos del programa, tiendas y material colectivo, y seguro de viaje y actividad con trekking hasta 5.100 m, rescate y repatriación."], ["Días de reserva", "Los dos días de reserva están incluidos en el precio. Si hay que utilizarlos, no tienen coste adicional. Si una situación exigiera más días, te informaríamos del nuevo programa y del coste antes de continuar."], ["Requisitos para participar", "Experiencia en travesías de varios días, conversación previa con el guía, revisión con medicina del viajero y pasaporte vigente. Hay que disponer de 13 días, más los vuelos."], ["Cómo se reserva", "Cuando se abran las reservas: conversación previa, dossier completo y contrato de viaje combinado. La plaza queda confirmada con una señal del 30 % y el resto se paga 45 días antes de salir. Precio: 2.700 € hasta 90 días antes y 2.850 € después. Andes Wild Trek actúa como organizador del viaje."], ["Cambios durante el viaje", "El guía puede modificar, acortar o detener una jornada por seguridad, meteorología o estado del grupo. Cada jornada tiene un plan B: la última se puede terminar en Curva con vehículo y, si hace falta, se evacua por las pistas. Estos cambios no tienen coste adicional."], ["Si se activa el plan C", "Si antes de salir el paso Sunchulli no es practicable o la zona minera no lo aconseja, la travesía se hace por Cañisaya y el camino del Akamani. El programa empieza con un traslado de La Paz a Curva y dura nueve días. El precio no cambia: se mantienen guías, mulas, comidas, alojamientos y traslados, y los dos días que se ahorran se suman a los de reserva. Te lo explicamos y lo aceptas antes de salir de La Paz."], ["Cancelación por tu parte", "Gastos sobre el precio total: 10 % a más de 90 días, 25 % de 90 a 61, 50 % de 60 a 31, 75 % de 30 a 15 y 100 % a menos de 15 días o si no te presentas. Puedes ceder la plaza a otra persona que cumpla los requisitos. Sin gastos si hay circunstancias inevitables y extraordinarias en destino. Condiciones pendientes de validar con asesoría."], ["Grupo privado", "Para grupos de 8 a 13 personas, con fechas a elegir dentro de la temporada (del 15 de junio al 31 de julio) y presupuesto a medida."]], "condNote": "Las reservas todavía no están abiertas. Fechas, precio y condiciones definitivas se confirmarán tras el reconocimiento del recorrido.", "tw": {"title": "Trabajo TD2 · Andes Wild Trek · Apolobamba", "nav": ["El viaje", "El trabajo", "Planes B y C", "Bloques", "Herramientas", "Evaluación", "Fuentes"], "eyebrow": "TRABAJO ACADÉMICO · TÉCNICO DEPORTIVO EN MEDIA MONTAÑA", "h1": "Andes Wild Trek<br>Apolobamba", "lead": "Proyecto de creación de una empresa de guiaje y de una travesía de seis jornadas entre Pelechuco y Charazani, Bolivia.", "meta": "Izan Pimentel Pérez · 24 de noviembre de 2026 · Documentos en catalán", "full": "Trabajo completo (PDF)", "word": "Versión editable (Word)", "back": "Ver la web del viaje", "keyLabel": "EL PROYECTO EN CUATRO PUNTOS", "keys": [["Empresa", "Agencia organizadora de viajes combinados con base en Cataluña y operador local en Bolivia."], ["Programa", "11 días y 2 de reserva: 3 de aclimatación, 1 de traslado, 6 jornadas a pie y 1 de regreso. Mejor época: de mediados de junio a finales de julio."], ["Presupuesto", "2.700 € por persona con un mínimo de 8 y un máximo de 13; margen objetivo del 20%."], ["Siguiente paso", "Reconocimiento de campo, cotizaciones locales y permisos antes de comercializar."]], "present": "Presentaciones", "presentOff": "Salir del modo exposición", "toolsLabel": "HERRAMIENTAS DEL GUÍA Y ANEXOS", "toolsTitle": "Para aplicarlo<br>sobre el terreno.", "tools": [["Formularios operativos", "10 páginas · PDF", "Checklist diario, encuesta, autoevaluación, informe de mejora y expediente de apertura.", "dossiers/Apolobamba_Formularis_Operatius.pdf"], ["Encuesta del cliente", "1 página · PDF · ca, es, en, fr", "Encuesta anónima de satisfacción que se entrega al acabar el viaje, en el idioma del cliente.", "dossiers/Enquesta_Satisfaccio_ES.pdf"], ["Atlas cartográfico", "11 láminas · PDF A3", "Mapa general con los planes B y C, las seis jornadas y las cuatro etapas del plan C, con perfil, puntos de paso, rutas de evacuación y GPX.", "dossiers/Apolobamba_Atles_Cartografic_A3.pdf"], ["Flyer con QR", "Imagen · JPG", "Pieza del plan de marketing con fotografía real; el QR abre la web del viaje.", "assets/flyer.jpg"], ["App del guía", "Móvil · sin cobertura", "Horario y luz en tiempo real, GPS sobre el trazado, horas límite y decisiones, mapa sin cobertura, planes B y C, meteo por puntos, SOS con coordenadas, listas y GPX.", "guia/"], ["Dossier completo del cliente", "15 páginas · PDF", "Documento que se envía al cliente cuando contacta: etapas punto a punto, mapas, clima y condiciones.", "dossiers/client/Dossier_Viaje_ES.pdf"]], "open": "Abrir", "sourcesLabel": "FUENTES", "sourcesTitle": "Contraste de la ruta", "mapLabel": "MAPA DEL TRABAJO", "mapTitle": "Cómo encajan las piezas.", "map": [["Empresa y mercado", [["Entorno laboral", "Modelo de agencia, público y DAFO", "empresa"], ["Normativa", "Titulación, contrato y seguros", "normativa"], ["Marketing", "Mensaje, campaña y flyer", "marketing"]]], ["Producto", [["Programa", "11 días + 2, seis jornadas y aclimatación", "empresa"], ["Presupuesto", "2.700 € con un mínimo de 8", "empresa"], ["Ficha del cliente", "Qué recibe quien se apunta", "client"]]], ["Operación", [["Metodología", "Conducción, dinámicas y evaluación", "metodologia"], ["Ficha del guía", "Horarios, puntos de decisión y mapas", "guia"], ["Formularios", "Checklist, encuesta y expediente", "eines"]]]], "mapBase": "Todo el trabajo descansa en dos límites: las competencias del TD2 en el paso Sunchulli y el reconocimiento de campo previo a la venta.", "planLabel": "TEMPORADA, PLANES B Y PLAN C", "planHeading": "Cuándo ir<br>y qué hacemos si no se puede pasar.", "planIntro": "Revisión del 17/11/2026 con fuentes de montañeros, operadores, la ABC y OpenStreetMap. Cada jornada tiene planes B y vías de evacuación, y el plan C es una ruta completa por el Akamani.", "planBTitle": "Planes B por jornada", "planCTitle": "Fichas técnicas del plan C", "roadsNote": "Consultado el", "colsC": ["Etapa", "Día", "Km", "Desnivel", "Máx.", "Duración", "Horario", "Noche"], "gpxB": "Descarga el plan B del día", "gpxC": "GPX del plan C", "gpxMain": "GPX de la ruta principal", "avalLabel": "INSTRUMENTOS DE EVALUACIÓN", "avalTitle": "Evaluar de verdad,<br>no solo sobre el papel.", "avalIntro": "La encuesta del cliente, el checklist diario y la autoevaluación del guía del Anexo A, convertidos en herramientas que se pueden usar. La encuesta es un formulario anónimo en cuatro idiomas; el checklist y la autoevaluación funcionan dentro de la app del guía, sin cobertura, y se exportan en CSV o PDF.", "avalQr": "Escanea para abrir la encuesta", "aval": [["Encuesta del cliente en línea", "Formulario de Google · anónimo · ca, es, en, fr", "El cliente elige el idioma y responde desde el móvil al terminar el viaje (unos 3 minutos). No se pide nombre ni correo; las respuestas van a una hoja de cálculo del responsable.", "https://docs.google.com/forms/d/e/1FAIpQLScnXaBFRML574r8K5PI5J7VZYa5B6C28ZPedfOIt_a5luli2g/viewform"], ["Checklist diario del guía", "App del guía · sin cobertura", "Doce comprobaciones antes de salir (Sí / No / NA), decisión de inicio y registro de la jornada. Se guarda en el móvil y se exporta en CSV o PDF.", "guia/?aval=check"], ["Autoevaluación del guía", "App del guía · sin cobertura", "Diez aspectos valorados de 1 a 5 con un hecho observable, media y cierre con la acción prioritaria. En las 72 horas posteriores al servicio.", "guia/?aval=auto"], ["QR de la encuesta", "Imagen · SVG", "Para imprimir en la libreta de ruta o enseñar desde la app el último día, para que cada cliente la abra con su móvil.", "assets/enquesta-qr.svg"]]}, "stageDossier": "Los puntos de paso, los mapas y los horarios detallados de cada jornada están en el dossier completo, que te enviamos cuando nos escribes.", "docRequest": "Pídelo", "seasonLabel": "CUÁNDO IR", "planTitle": "Si el camino no deja pasar", "planText": "Cada jornada tiene un plan B preparado y hay una ruta alternativa completa. Si hay que cambiar, el guía lo decide pensando en la seguridad del grupo.", "planItems": [["Paso Sunchulli (5.032 m)", "Hay hora límite: las 14:40. Si no llegamos a tiempo, si hay nieve dura o hielo o si el tiempo es malo, volvemos a Hilo Hilo y usamos un día de reserva."], ["Bajada de las Mil Curvas", "Con nieve, hielo o poca visibilidad no entramos. Hay una bajada alternativa más larga y menos empinada, o podemos dormir en la comunidad de Quellwa Cota."], ["Final de la travesía", "Si vamos justos de tiempo, terminamos en Curva y seguimos en vehículo hasta Charazani."], ["Plan C · por el Akamani", "Si el paso Sunchulli no es practicable o la zona minera no lo aconseja, hacemos la travesía por Cañisaya y el camino del Akamani hasta Charazani: cuatro jornadas, 35 km y un máximo de 4.661 m."], ["Pistas y evacuación", "Cerca de un tercio del camino va por pistas mineras. A cambio, en casi todo el recorrido un vehículo puede llegar si hay que evacuar a alguien."]], "levelLabel": "01 / NIVEL Y REQUISITOS", "levelTitle": "¿Es para ti?<br>Míralo antes.", "levelIntro": "Cuatro indicadores para saber, de un vistazo, qué pide la travesía. La dificultad técnica es baja: lo que la hace exigente es la duración, la altitud y el aislamiento.", "levels": [["Exigencia física", 3, "Alta", "Jornadas de hasta 9 h 30, seis días seguidos, y casi 1.500 m de bajada el último día."], ["Dificultad técnica", 1, "Baja", "Sendero y pista, sin trepadas. No hacen falta crampones ni piolet: con nieve dura o hielo, no se cruza."], ["Altitud", 4, "Muy alta", "Cinco noches por encima de los 4.000 m y un paso a 5.032 m. Hace falta aclimatación y no todo el mundo se adapta igual."], ["Aislamiento", 3, "Alto", "Sin cobertura de móvil. Una evacuación puede tardar horas o un día, por pista o a pie."]], "reqTitle": "Requisitos para participar", "reqs": ["Haber hecho al menos una travesía de 3 días o más con mochila y noches fuera de casa.", "Poder caminar 8–9 horas con unos 1.000 m de desnivel y repetirlo al día siguiente.", "Revisión en un centro de medicina del viajero y ninguna contraindicación para la altitud.", "Pasaporte vigente y 13 días libres, más los vuelos.", "Aceptar las decisiones del guía sobre ritmo, retiradas y planes alternativos."], "meetTitle": "Punto de encuentro", "meetText": "Día 1, aeropuerto internacional de El Alto (La Paz, LPB): te recogemos cuando llega tu vuelo y te llevamos al hotel. Reunión de bienvenida a las 19:00 en el hotel. El servicio termina el día 11 por la tarde, al llegar a La Paz.", "earlyLabel": "Reserva anticipada · hasta 90 días antes", "stdLabel": "A menos de 90 días de la salida", "priceStd": "2.850", "guarantee": ["Garantía de salida", "Si no se llega a 8 personas, te avisamos como mínimo 30 días antes y te devolvemos el 100 % de lo que hayas pagado en 14 días, o te guardamos la plaza para otra fecha, como prefieras."], "extrasTitle": "Suplementos opcionales", "extras": [["Habitación individual (hoteles de La Paz, Pelechuco y Charazani)", "Precio a confirmar"], ["Tienda individual", "Precio a confirmar"], ["Alquiler de saco de dormir de −10 °C", "Precio a confirmar"], ["Noches en La Paz después del día 11 si no se usan los días de reserva", "A tu cargo; te ayudamos a reservar"]], "bookTitle": "Cómo se reserva", "bookSteps": [["Escríbenos", "Por WhatsApp, con la fecha que te interesa y tu experiencia."], ["Conversación previa", "Hablamos de tu experiencia, salud y expectativas para ver si la travesía es para ti."], ["Dossier y contrato", "Te pasamos el dossier completo y el contrato de viaje combinado."], ["Señal y confirmación", "Pagas la señal del 30 % y la plaza queda confirmada. El resto, 45 días antes de salir."]], "cancelTitle": "Si tienes que cancelar", "cancelCols": ["Cuándo cancelas", "Gastos sobre el precio total"], "cancelRows": [["Más de 90 días antes", "10 %"], ["De 90 a 61 días", "25 %"], ["De 60 a 31 días", "50 %"], ["De 30 a 15 días", "75 %"], ["Menos de 15 días o no presentarse", "100 %"]], "cancelNotes": ["Puedes ceder la plaza a otra persona que cumpla los requisitos; solo pagas los gastos del cambio.", "Sin gastos si en destino hay circunstancias inevitables y extraordinarias que impidan el viaje.", "Te recomendamos un seguro de cancelación, que no está incluido."], "privateTitle": "Grupo privado", "privateText": "Si sois un grupo de 8 a 13 personas, podéis elegir las fechas dentro de la temporada (del 15 de junio al 31 de julio). Os hacemos un presupuesto a medida.", "gearOrgTitle": "Lo pone la organización", "gearOrg": ["Tiendas, cocina y todas las comidas de la travesía", "Mulas para el equipaje", "Botiquín de grupo y pulsioxímetro", "Comunicador por satélite", "Material de seguridad del grupo"], "levelWord": "Nivel", "foldMore": "Ver más", "foldLess": "Ver menos", "stagePhotoAlt": ["Calle empedrada de Pelechuco, donde empieza la travesía", "Llama y cumbres nevadas en el Área Natural de Manejo Integrado Apolobamba", "Cresta rocosa y nieve en la alta montaña de Apolobamba", "Cresta y valles con lagunas en el Área Natural de Manejo Integrado Apolobamba", "La cordillera de Apolobamba vista desde el camino a Charazani", "El valle entre Charazani y Curva, la última jornada"], "stagePhotoNote": "Foto de referencia del paisaje de la zona: no es necesariamente el punto exacto de la jornada.", "planShort": [["B", "Un plan B para cada jornada", "Si el tiempo, el terreno o el grupo no acompañan, volvemos atrás, acortamos la jornada o seguimos en vehículo."], ["+2", "Dos días de reserva", "Incluidos en el precio, para esperar mejor tiempo o aclimatarnos más."], ["C", "Una ruta alternativa completa", "Si el paso principal no es practicable, hacemos la travesía por otro camino hasta Charazani."]], "seasonShort": [["Junio y julio", "El corazón de la estación seca: tiempo más estable y noches frías."], ["Mayo y septiembre", "Posibles, pero con más lluvias o tormentas de tarde."], ["Agosto", "Puede nevar fuerte en los pasos: solo con previsión estable."], ["De diciembre a abril", "Estación de lluvias: no vamos."]]}, "en": {"planShort": [["B", "A plan B for every day", "If the weather, the terrain or the group are not up to it, we turn back, shorten the day or continue by vehicle."], ["+2", "Two reserve days", "Included in the price, to wait for better weather or acclimatise more."], ["C", "A complete alternative route", "If the main pass is not passable, we do the trek by another path to Charazani."]], "seasonShort": [["June and July", "The heart of the dry season: more stable weather and cold nights."], ["May and September", "Possible, but with more rain or afternoon storms."], ["August", "Heavy snow is possible on the passes: only with a stable forecast."], ["December to April", "Rainy season: we don’t go."]], "stagePhotoAlt": ["Cobbled street in Pelechuco, where the trek begins", "Llama and snowy peaks in the Apolobamba Integrated Management Natural Area", "Rocky ridge and snow in the high mountains of Apolobamba", "Ridge and valleys with lakes in the Apolobamba Integrated Management Natural Area", "The Apolobamba range seen from the road to Charazani", "The valley between Charazani and Curva, on the last day"], "stagePhotoNote": "Reference photo of the area’s landscape: not necessarily the exact spot of the day.", "skip": "Skip to content", "foldMore": "Show more", "foldLess": "Show less", "nav": ["Level", "The stages", "The programme", "Price", "The guide", "Preparation", "Questions", "Documents"], "menu": "Open menu", "close": "Close", "pdf": "Trip sheet", "langLabel": "Language", "heroLabel": "BOLIVIA · CORDILLERA APOLOBAMBA", "heroTitle": "Apolobamba.<em>The trail brings us together.</em>", "heroText": "Six days on foot between Pelechuco and Charazani, on shepherds’ paths and over a pass above 5,000 m. Small group, mountain guide and local guide.", "heroCta": "Discover the trek", "heroSecond": "See the day-by-day programme", "heroDate": "June 2027 · best season: mid-June to late July", "photoNote": "Real Apolobamba landscape", "facts": [["6", "walking days"], ["53 km", "from Pelechuco to Charazani"], ["5,032 m", "Sunchulli Pass, the highest point"], ["11 + 2", "programme and reserve days"]], "storyLabel": "02 / THE EXPERIENCE", "storyTitle": "Walking far.<br>Feeling close.", "storyLead": "Some journeys are measured in kilometres. This one is also measured in what we learn along the way.", "storyText": "From Pelechuco to Charazani, the trek links Andean valleys, high passes and grazing land at the foot of the Apolobamba glaciers. It is a demanding, little-travelled route that we walk without rushing, with time for local knowledge and for each other.", "storyCaption": "From the trail to Charazani", "values": [["A living land", "We read the landscape with respect for the communities and their knowledge."], ["A group that walks together", "Shared pace, regrouping and clear instructions."], ["Careful preparation", "Mountain guide and local guide, with a programme designed for good acclimatisation."]], "routeLabel": "03 / THE STAGES", "routeTitle": "One trail.<br>Six days to live it.", "routeIntro": "We always walk in daylight: departure from 07:10 and arrival at camp before 16:40, Bolivian time. Choose a day to see its key figures.", "stageLabel": "Day", "distance": "Distance", "ascent": "Ascent", "descent": "Descent", "duration": "11 days / 10 nights / 6 walking days, + 2 reserve days", "max": "Highest point", "stageFocus": "Key to the day", "routeNote": "53.4 km in total. Distances and height gains are approximate and the times are planning times: the route still has to be checked on the ground before bookings open. About a third of the trail follows tracks opened by mining.", "stageNames": ["Pelechuco → Camp 1", "Camp 1 → Hilo Hilo", "Hilo Hilo → Camp 2", "Camp 2 → Incacancha", "Incacancha → Camp 3", "Camp 3 → Charazani"], "stageDescriptions": ["We leave Pelechuco and climb steadily to the first pass at 4,706 m, mostly on the mining track that crosses it. We drop into the Kotani valley and camp at the valley floor. A day to find the group’s pace and see how everyone responds to altitude.", "A short, easy day, almost all on a track, to the community of Hilo Hilo. We sleep a little lower than the night before and spend the afternoon resting, drinking and preparing the next day’s high pass.", "The big day of the trek. We climb the valley to the Sunchulli Pass, above 5,000 m with glaciers close by, and descend to camp in the Sunchulli valley, an old mining area.", "Three linked passes above 4,500 m and the long zigzag descent of the Mil Curvas down to Incacancha, where we camp by the waterfalls.", "Short in distance, intense in height gain. We climb to the Akamani Pass, below the sacred mountain of the Kallawaya, pass the Tambillo apacheta and descend to camp.", "A long descent to the inhabited valleys: Curva junction, bridge over the river, a last climb and arrival in Charazani."], "stageFocusText": ["Over 1,000 m of sustained ascent and the first night in a tent at 4,168 m.", "Recovery day: walk little, drink plenty and sleep well.", "Cut-off time at the pass: 14:40. With hard snow or ice on the pass, the day is not done.", "The descent of the Mil Curvas needs care if the ground is wet or icy.", "The short distance is deceptive: 600 m of concentrated ascent and accumulated fatigue.", "If we are short of time at the Curva junction, we finish there and do the last stretch by vehicle."], "journeyLabel": "04 / THE PROGRAMME", "journeyTitle": "Eleven days,<br>step by step.", "journeyIntro": "Three days in La Paz to acclimatise, one transfer day, six walking days and one return day.", "reserveTitle": "+ 2 reserve days", "reserveText": "We use them if more acclimatisation is needed, if the weather forces us to wait or if something unexpected happens. That is why you need 13 days, plus flights.", "methodLabel": "HOW WE WORK", "methodTitle": "Good preparation shows<br>at every step.", "methodIntro": "How we guide is part of the experience. Prepare, observe, explain and learn to improve.", "methodSteps": [["Before walking", "A prior conversation about experience and expectations, a group meeting and clear information on level, gear and possible changes."], ["Every morning", "Short briefing: the day’s goal, conditions, water, decision points and how the group is."], ["During the day", "Group pace, regrouping and explanations about landscape and culture in suitable places. On the Sunchulli Pass day, walking comes first."], ["After the trip", "Daily review with the group, anonymous survey and an improvement plan for the next departure."]], "respectTitle": "The land walks with us too.", "respectText": "Local knowledge, agreements with the communities, respect for the trails and responsible handling of waste and water. Visits and photos of people are only with permission.", "prepLabel": "06 / PREPARATION", "prepTitle": "A good backpack.<br>Good preparation.", "prepIntro": "For people with multi-day trekking experience, able to handle long days and flexible enough to live with tents, cold and changes of plan.", "gearTitle": "Your gear list", "gearHint": "Tick what you already have ready. Compulsory items are checked in La Paz before departure.", "gearCount": "items ready", "reset": "Untick all", "saved": "Your ticks are only saved in this browser. No data is sent.", "gearGroups": [["Compulsory · clothing and sleeping", ["Broken-in mountain boots", "Waterproof jacket and trousers", "Down or synthetic jacket", "Gloves, hat and neck gaiter", "Sleeping bag with −10 °C comfort rating and mat"]], ["Compulsory · daypack", ["25–35 litre backpack", "Bottles for 2–3 litres and water treatment", "Head torch with spare batteries or power", "Category 3–4 sunglasses and sun cream", "Passport, insurance and personal medication"]], ["Recommended", ["Trekking poles", "Thermal layers and spare socks", "Spare food for the trail", "Power bank", "Personal first-aid kit and a bag for your waste"]]], "altitudeTitle": "Altitude asks you to listen.", "altitudeText": "Being fit does not guarantee adapting well. We spend five nights above 4,000 m and cross a pass above 5,000 m. A travel-medicine check-up is needed before the trip.", "altitudePoints": ["Tell the guide about any discomfort.", "With symptoms, we do not go higher to sleep.", "If the group needs it, the programme is extended or changed."], "priceLabel": "05 / REFERENCE PRICE", "priceTitle": "Knowing what lies<br>behind the trip.", "priceNote": "Reference price with early booking, for a minimum group of 8 people and a maximum of 13. It is a project estimate, pending real quotes from local suppliers.", "perPerson": "per person", "included": "What’s included", "includeItems": ["Mountain guide and local guide", "Transfers La Paz–Pelechuco and Charazani–La Paz (La Paz–Curva if plan C is used)", "Mules and load support", "Meals and accommodation for the whole programme", "Tents and group equipment", "Travel and activity insurance"], "excluded": "What’s not included", "excludeItems": ["International flights", "Personal gear: sleeping bag, mat, clothing and boots", "Personal expenses and tips"], "priceDisclaimer": "Bookings are not open yet. Dates, price and services will be confirmed after the route has been checked.", "priceCta": "See the conditions", "docsLabel": "08 / DOCUMENTS", "docsTitle": "Everything you need<br>to prepare the trip.", "docsIntro": "Documents to read calmly, print or carry on your phone. We send you the full dossier personally.", "docs": [["Trip sheet", "2 pages · PDF", "Level, requirements, day-by-day programme, meeting point, price, booking and cancellation."], ["Preparation and gear", "2 pages · PDF", "Health and altitude, documents, what the mules carry and a gear checklist."], ["Training plan", "12 weeks · PDF", "What to do each week to arrive ready, with strength work and gear tests."], ["Full trip dossier", "PDF · via WhatsApp", "Stages point by point with maps and times, June climate, accommodation, preparation and conditions. We send it when you write to us."]], "download": "Download", "sourcesLabel": "Sources we used to check the route", "sourcesText": "The route is based on a 2012 GPS track, brought up to date with recent information: walkers’ accounts and tracks from 2022–2025, Bolivian operators’ programmes checked in 2026 and OpenStreetMap, which shows that about a third of the way is now a mining track. None of these sources replaces checking the route on the ground.", "sourcesButton": "See the sources", "sources": [["GPS track · Gallotrekk (Wikiloc)", "Real 2012 record of the route: line, waypoints and time for each stage."], ["Operator · Bolivian Mountain Guides", "Pelechuco–Charazani programme: camps at Palca, Sunchulli and Jatunpampa; Sunchulli Pass at 5,100 m."], ["Operator · Kaleidoscope Travel", "Camp by the Illo Illo river and about 6 h to Sunchulli; finish at Curva."], ["Operator · ZigZag Bolivia", "About 9 h from Palca to Sunchulli with no intermediate night; camp at 4,500 m."], ["2022 · Colli expedition", "Interview with members of a five-day trek along the same corridor."], ["2022 · Hiker’s track", "Track published on Wikiloc; it does not cover the final stretch to Charazani."], ["2024 · Video account", "Video of the Pelechuco–Charazani trek, published in October 2024."], ["2025 · Access to Pelechuco", "Account of the 4×4 journey to Pelechuco."]], "faqLabel": "07 / BEFORE YOU DECIDE", "faqTitle": "Questions from the trail.", "faqs": [["Is it suitable as a first trek?", "No. It is designed for hikers with multi-day trekking experience, used to long days and sleeping in tents. Before booking we talk to assess preparation and expectations."], ["How many days do I need?", "The programme lasts 11 days: three acclimatisation days in La Paz, one transfer, six walking days and one return day. We add two reserve days, so you need 13 days, plus flights."], ["Which is the hardest day?", "The Sunchulli Pass day, day 7: 11.4 km, about 1,060 m of ascent, 7 to 9 hours and a pass above 5,000 m. That is why the day before is short and we sleep in Hilo Hilo."], ["Where do we sleep?", "Hotel in La Paz, simple local lodging in Pelechuco and Charazani and five nights in tents between 4,000 and 4,700 m. Nights are cold, often below zero."], ["When is the best season?", "From mid-June to late July, the heart of the dry season. May and September are possible but less certain, and in August there has been heavy snow on the Sunchulli Pass. We propose the second half of June 2027."], ["Do I have to carry all my luggage?", "No. Mules carry tents, kitchen and luggage; during the day you carry a backpack with warm clothes, water and food."], ["Is the water drinkable?", "Not straight away. There is gold mining in the area and treating the water does not remove metals: we only take it from springs above the mines or confirmed by the community, always treat it and carry a reserve on the Sunchulli section."], ["What happens in bad weather or if someone is unwell?", "The guide can stop, shorten or change a day, and every day has a plan B ready. We have two reserve days, a complete alternative route (plan C, via Cañisaya and the Akamani) and, along most of the route, vehicle access if needed. With hard snow or ice on the passes, we do not cross."], ["Do I need insurance?", "The price includes travel and activity insurance covering trekking up to 5,100 m, rescue and repatriation. If you already have one, check with us to avoid duplicate cover."], ["Has the route been checked on the ground?", "Not yet. The programme starts from a 2012 GPS track and has been checked against walkers’ accounts from 2022–2025, Bolivian operators’ itineraries and OpenStreetMap, where the mining tracks already appear. Before bookings open, the passes, camps, water and the last day’s bridge must be checked."], ["Can I book already?", "Not yet. This website presents an academic project for a mountain sports technician qualification (TD2). June 2027 is a proposed date; bookings would open after validating the route, services, permits and insurance."]], "endLabel": "THE FIRST STEP", "endTitle": "Get to know the trip.<br>Prepare your way.", "endText": "Look at the full programme and check whether it matches your experience.", "footerLine": "Mountains, land and a shared trail.", "footerNote": "TD2 academic project · Izan Pimentel Pérez", "privacy": "Privacy", "terms": "Project conditions", "credits": "Photography and maps", "privacyText": "This website does not collect bookings or personal data. The language and the gear-list ticks are only saved in your browser and you can delete them with the page controls. External links have their own terms.", "termsText": "Andes Wild Trek is an academic project for a mountain sports technician qualification (TD2). Dates, price and services are indicative and are not a binding offer. Before bookings open, the route, suppliers, permits, insurance and contract terms must be validated.", "creditIntro": "Documentary photographs of Apolobamba and Pelechuco, with author and licence identified. Their date does not certify the current state of the route.", "mapNotice": "The maps use OpenStreetMap and SRTM data and the OpenTopoMap style, CC-BY-SA. The main route is based on a 2012 GPS track; tracks and alternative routes come from OpenStreetMap.", "dismiss": "Close the window", "notice": "", "dayWord": "Day", "night": "Where we sleep", "schedule": "Planned times", "scheduleText": "Departure {0} · arrival {1}", "approx": "approx.", "stageTabs": ["Camp 1", "Hilo Hilo", "Sunchulli Pass", "Incacancha", "Akamani", "Charazani"], "itinCols": ["Day", "Stage", "What we do", "Night"], "itinerary": [["1", "Arrival in La Paz", "Pick-up at El Alto airport, transfer to the hotel and welcome meeting at 19:00.", "Hotel · 3,650 m"], ["2", "Adapting in La Paz", "Easy walk around the city, drinking and rest.", "Hotel · 3,650 m"], ["3", "Acclimatisation and preparation", "Moderate walk, gear check and briefing meeting.", "Hotel · 3,650 m"], ["4", "La Paz → Pelechuco", "4×4 transfer via Lake Titicaca and the Ulla Ulla plateau. About 12 hours.", "Local lodging · 3,660 m"], ["5", "Pelechuco → Camp 1", "9.7 km · +1,047 m · 6–8 h", "Tent · 4,168 m"], ["6", "Camp 1 → Hilo Hilo", "4.2 km · 2–3 h · afternoon rest", "Tent · 4,010 m"], ["7", "Hilo Hilo → Sunchulli Pass → Camp 2", "11.4 km · +1,062 m · 7–9 h", "Tent · 4,500–4,700 m"], ["8", "Camp 2 → Incacancha", "8.3 km · −867 m · 5–7 h", "Tent · 4,060 m"], ["9", "Incacancha → Camp 3", "4.1 km · +602 m · 4–6 h", "Tent · 4,171 m"], ["10", "Camp 3 → Charazani", "15.8 km · −1,473 m · 8–9 h 30 min", "Local lodging · 3,195 m"], ["11", "Charazani → La Paz", "Return by vehicle (7–8 hours) and farewell.", "End of trip"]], "priceAmount": "2,700", "hubLabel": "THE PROJECT BLOCK BY BLOCK", "hubTitle": "The project,<br>block by block.", "hubIntro": "The six blocks of the project, as PDFs (in Catalan). You can open them, download them or search their content.", "hubFull": "Full project", "hubChanges": "Changes and pending decisions", "hubSearch": "Search the project", "hubSearchPh": "Budget, permits, checklist, Sunchulli…", "hubPresent": "Presentation mode", "hubPresentOff": "Exit presentation mode", "hubCount": "{0} of 6 blocks", "hubPages": "pages", "hubMeta": "PDF · Catalan", "hubOpen": "Open PDF", "hubDownload": "Download", "hubRead": "Read the text here", "hubNav": "Project blocks", "igLabel": "INSTAGRAM / ACADEMIC MOCK-UP", "igText": "Six sample posts from the eight-week campaign. It is a mock-up of the marketing plan, not a real account.", "igCta": "See the marketing plan", "igPosts": ["Six days, one trail. Introducing the trek.", "5,032 m: Sunchulli Pass day.", "Pelechuco, where it all begins.", "What’s in my backpack? The list is on the website.", "Small group: 8 to 13 people.", "Three days in La Paz before walking."], "igCredit": "Photos: Realnif, Raullike and Das Morton · Wikimedia Commons · CC BY-SA 4.0.", "treballNav": "TD2 project", "condLabel": "TRIP CONDITIONS", "condTitle": "Clear conditions from the start.", "conds": [["Minimum and maximum group", "The trip runs with a minimum of 8 people and a maximum of 13. If the minimum is not reached, we tell you at least 30 days before and refund 100 % of what you have paid within 14 days, or keep your place for another date."], ["What the price includes", "Mountain guide and local guide (with 10–13 people local support is added), 4×4 transfers in the programme, mules, all meals and accommodation in the programme, tents and group equipment, and travel and activity insurance with trekking up to 5,100 m, rescue and repatriation."], ["Reserve days", "The two reserve days are included in the price. If they are used, there is no extra cost. If a situation required more days, we would tell you the new programme and its cost before continuing."], ["Requirements to take part", "Multi-day trekking experience, a prior conversation with the guide, a travel-medicine check-up and a valid passport. You need 13 days, plus flights."], ["How to book", "When bookings open: prior conversation, full dossier and package travel contract. Your place is confirmed with a 30 % deposit and the rest is paid 45 days before departure. Price: 2,700 € up to 90 days before and 2,850 € afterwards. Andes Wild Trek acts as the trip organiser."], ["Changes during the trip", "The guide can change, shorten or stop a day for safety, weather or the state of the group. Every day has a plan B: the last one can end at Curva by vehicle and, if needed, evacuation uses the tracks. These changes have no extra cost."], ["If plan C is used", "If before leaving the Sunchulli Pass is not passable or the mining area makes it unwise, the trek goes via Cañisaya and the Akamani trail. The programme starts with a transfer from La Paz to Curva and lasts nine days. The price does not change: guides, mules, meals, accommodation and transfers are kept, and the two days saved are added to the reserve days. We explain it and you agree to it before leaving La Paz."], ["If you cancel", "Charges on the total price: 10 % more than 90 days before, 25 % from 90 to 61, 50 % from 60 to 31, 75 % from 30 to 15 and 100 % less than 15 days before or for a no-show. You can transfer your place to someone who meets the requirements. No charge in unavoidable and extraordinary circumstances at the destination. Conditions pending legal review."], ["Private group", "For groups of 8 to 13 people, with dates of your choice within the season (15 June to 31 July) and a tailored quote."]], "condNote": "Bookings are not open yet. Final dates, price and conditions will be confirmed after the route has been checked.", "stageDossier": "Waypoints, maps and detailed times for each day are in the full dossier, which we send when you write to us.", "docRequest": "Ask for it", "seasonLabel": "WHEN TO GO", "planTitle": "If the trail won’t let us through", "planText": "Every day has a plan B ready and there is a complete alternative route. If we need to change, the guide decides with the group’s safety in mind.", "planItems": [["Sunchulli Pass (5,032 m)", "There is a cut-off time: 14:40. If we don’t get there in time, if there is hard snow or ice or if the weather is bad, we return to Hilo Hilo and use a reserve day."], ["Mil Curvas descent", "With snow, ice or poor visibility we don’t go in. There is a longer, less steep alternative descent, or we can sleep in the community of Quellwa Cota."], ["End of the trek", "If we are short of time, we finish at Curva and continue by vehicle to Charazani."], ["Plan C · via the Akamani", "If the Sunchulli Pass is not passable or the mining area makes it unwise, we do the trek via Cañisaya and the Akamani trail to Charazani: four days, 35 km and a high point of 4,661 m."], ["Tracks and evacuation", "About a third of the trail follows mining tracks. In return, along most of the route a vehicle can get there if someone needs evacuating."]], "tw": {"title": "TD2 project · Andes Wild Trek · Apolobamba", "nav": ["The trip", "The project", "Plans B and C", "Blocks", "Tools", "Evaluation", "Sources"], "eyebrow": "ACADEMIC PROJECT · MOUNTAIN SPORTS TECHNICIAN (MID-MOUNTAIN)", "h1": "Andes Wild Trek<br>Apolobamba", "lead": "Project to create a guiding company and a six-day trek between Pelechuco and Charazani, Bolivia.", "meta": "Izan Pimentel Pérez · 24 November 2026 · Documents in Catalan", "full": "Full project (PDF)", "word": "Editable version (Word)", "back": "See the trip website", "keyLabel": "THE PROJECT IN FOUR POINTS", "keys": [["Company", "Package-travel organiser based in Catalonia with a local operator in Bolivia."], ["Programme", "11 days and 2 in reserve: 3 acclimatisation, 1 transfer, 6 walking and 1 return. Best season: mid-June to late July."], ["Budget", "€2,700 per person with a minimum of 8 and a maximum of 13; target margin 20%."], ["Next step", "Field reconnaissance, local quotes and permits before selling."]], "present": "Presentations", "presentOff": "Exit presentation mode", "toolsLabel": "GUIDE TOOLS AND ANNEXES", "toolsTitle": "To apply it<br>on the ground.", "tools": [["Operational forms", "10 pages · PDF", "Daily checklist, survey, self-assessment, improvement report and opening file.", "dossiers/Apolobamba_Formularis_Operatius.pdf"], ["Client survey", "1 page · PDF · ca, es, en, fr", "Anonymous satisfaction survey handed out at the end of the trip, in the client’s language.", "dossiers/Enquesta_Satisfaccio_EN.pdf"], ["Map atlas", "11 sheets · A3 PDF", "General map with plans B and C, the six walking days and the four plan C stages, with profile, waypoints, evacuation routes and GPX.", "dossiers/Apolobamba_Atles_Cartografic_A3.pdf"], ["Flyer with QR", "Image · JPG", "Marketing piece with a real photo; the QR opens the trip website.", "assets/flyer.jpg"], ["Guide app", "Mobile · offline", "Real-time schedule and daylight, GPS on the route, cut-off times and decisions, offline map, plans B and C, weather by point, SOS with coordinates, checklists and GPX.", "guia/"], ["Full client dossier", "15 pages · PDF", "Document sent to the client when they get in touch: stages point by point, maps, climate and conditions.", "dossiers/client/Travel_Dossier_EN.pdf"]], "avalLabel": "EVALUATION TOOLS", "avalTitle": "Evaluating for real,<br>not just on paper.", "avalIntro": "The client survey, the daily checklist and the guide self-assessment from Annex A, turned into tools that can actually be used. The survey is an anonymous form in four languages; the checklist and self-assessment work inside the guide app, offline, and export to CSV or PDF.", "avalQr": "Scan to open the survey", "aval": [["Online client survey", "Google form · anonymous · ca, es, en, fr", "Clients choose their language and answer on their phone at the end of the trip (about 3 minutes). No name or email is asked; answers go to a spreadsheet kept by the person in charge.", "https://docs.google.com/forms/d/e/1FAIpQLScnXaBFRML574r8K5PI5J7VZYa5B6C28ZPedfOIt_a5luli2g/viewform"], ["Guide’s daily checklist", "Guide app · offline", "Twelve checks before setting off (Yes / No / NA), start decision and day record. Saved on the phone and exported to CSV or PDF.", "guia/?aval=check"], ["Guide self-assessment", "Guide app · offline", "Ten aspects scored from 1 to 5 with an observable fact, average and a closing priority action. Within 72 hours after the service.", "guia/?aval=auto"], ["Survey QR code", "Image · SVG", "To print in the route notebook or show from the app on the last day, so each client opens it on their own phone.", "assets/enquesta-qr.svg"]], "open": "Open", "sourcesLabel": "SOURCES", "sourcesTitle": "Checking the route", "mapLabel": "PROJECT MAP", "mapTitle": "How the pieces fit.", "map": [["Company and market", [["Work environment", "Agency model, audience and SWOT", "empresa"], ["Regulations", "Qualification, contract and insurance", "normativa"], ["Marketing", "Message, campaign and flyer", "marketing"]]], ["Product", [["Programme", "11 + 2 days, six walking days and acclimatisation", "empresa"], ["Budget", "€2,700 with a minimum of 8", "empresa"], ["Client sheet", "What participants receive", "client"]]], ["Operations", [["Methodology", "Leading, group dynamics and evaluation", "metodologia"], ["Guide sheet", "Times, decision points and maps", "guia"], ["Forms", "Checklist, survey and file", "eines"]]]], "mapBase": "The whole project rests on two limits: the TD2 competences at the Sunchulli Pass and field reconnaissance before selling.", "planLabel": "SEASON, PLANS B AND PLAN C", "planHeading": "When to go<br>and what we do if we can’t get through.", "planIntro": "Review of 17/11/2026 with mountaineers’ accounts, operators, the ABC road authority and OpenStreetMap. Every day has plans B and evacuation routes, and plan C is a complete route via the Akamani.", "planBTitle": "Plans B by day", "planCTitle": "Plan C technical sheets", "roadsNote": "Checked on", "colsC": ["Stage", "Day", "Km", "Height gain", "Max.", "Duration", "Times", "Night"], "gpxB": "Download the plan B for day", "gpxC": "Plan C GPX", "gpxMain": "Main route GPX"}, "levelLabel": "01 / LEVEL AND REQUIREMENTS", "levelTitle": "Is it for you?<br>Check first.", "levelIntro": "Four indicators to see at a glance what the trek demands. Technical difficulty is low: what makes it demanding is its length, the altitude and the isolation.", "levels": [["Physical demand", 3, "High", "Days of up to 9 h 30, six days in a row, and almost 1,500 m of descent on the last day."], ["Technical difficulty", 1, "Low", "Trails and tracks, no scrambling. No crampons or ice axe needed: with hard snow or ice, we do not cross."], ["Altitude", 4, "Very high", "Five nights above 4,000 m and a pass at 5,032 m. Acclimatisation is needed and not everyone adapts in the same way."], ["Isolation", 3, "High", "No mobile coverage. An evacuation can take hours or a day, by track or on foot."]], "reqTitle": "Requirements to take part", "reqs": ["At least one previous trek of 3 days or more with a backpack and nights away.", "Able to walk 8–9 hours with about 1,000 m of ascent and do it again the next day.", "A travel-medicine check-up with no contraindication for altitude.", "Valid passport and 13 free days, plus flights.", "Accept the guide’s decisions on pace, retreats and alternative plans."], "meetTitle": "Meeting point", "meetText": "Day 1, El Alto International Airport (La Paz, LPB): we pick you up when your flight arrives and take you to the hotel. Welcome meeting at 19:00 at the hotel. The service ends on day 11 in the afternoon, on arrival in La Paz.", "earlyLabel": "Early booking · up to 90 days before", "stdLabel": "Less than 90 days before departure", "priceStd": "2,850", "guarantee": ["Departure guarantee", "If the group does not reach 8 people, we tell you at least 30 days before and refund 100 % of what you have paid within 14 days, or keep your place for another date, as you prefer."], "extrasTitle": "Optional supplements", "extras": [["Single room (hotels in La Paz, Pelechuco and Charazani)", "Price to be confirmed"], ["Single tent", "Price to be confirmed"], ["Hire of a −10 °C sleeping bag", "Price to be confirmed"], ["Nights in La Paz after day 11 if the reserve days are not used", "At your expense; we help you book"]], "bookTitle": "How to book", "bookSteps": [["Write to us", "By WhatsApp, with the date you are interested in and your experience."], ["Prior conversation", "We talk about your experience, health and expectations to see if the trek is right for you."], ["Dossier and contract", "We send you the full dossier and the package travel contract."], ["Deposit and confirmation", "You pay a 30 % deposit and your place is confirmed. The rest, 45 days before departure."]], "cancelTitle": "If you have to cancel", "cancelCols": ["When you cancel", "Charge on the total price"], "cancelRows": [["More than 90 days before", "10 %"], ["90 to 61 days", "25 %"], ["60 to 31 days", "50 %"], ["30 to 15 days", "75 %"], ["Less than 15 days or no-show", "100 %"]], "cancelNotes": ["You can transfer your place to someone who meets the requirements; you only pay the cost of the change.", "No charge if unavoidable and extraordinary circumstances at the destination prevent the trip.", "We recommend cancellation insurance, which is not included."], "privateTitle": "Private group", "privateText": "If you are a group of 8 to 13 people, you can choose your dates within the season (15 June to 31 July). We prepare a tailored quote.", "gearOrgTitle": "Provided by the organisation", "gearOrg": ["Tents, kitchen and all meals on the trek", "Mules for the luggage", "Group first-aid kit and pulse oximeter", "Satellite communicator", "Group safety equipment"], "levelWord": "Level"}, "fr": {"planShort": [["B", "Un plan B pour chaque journée", "Si la météo, le terrain ou le groupe ne suivent pas, nous faisons demi-tour, raccourcissons la journée ou continuons en véhicule."], ["+2", "Deux jours de réserve", "Inclus dans le prix, pour attendre une meilleure météo ou mieux s’acclimater."], ["C", "Un itinéraire alternatif complet", "Si le col principal n’est pas praticable, nous faisons la traversée par un autre chemin jusqu’à Charazani."]], "seasonShort": [["Juin et juillet", "Le cœur de la saison sèche : temps plus stable et nuits froides."], ["Mai et septembre", "Possibles, mais avec plus de pluie ou d’orages l’après-midi."], ["Août", "Il peut neiger fort sur les cols : seulement avec une prévision stable."], ["De décembre à avril", "Saison des pluies : nous n’y allons pas."]], "stagePhotoAlt": ["Rue pavée de Pelechuco, où commence la traversée", "Lama et sommets enneigés dans l’Aire naturelle de gestion intégrée Apolobamba", "Crête rocheuse et neige en haute montagne dans l’Apolobamba", "Crête et vallées avec lagunes dans l’Aire naturelle de gestion intégrée Apolobamba", "La cordillère d’Apolobamba vue depuis la route de Charazani", "La vallée entre Charazani et Curva, le dernier jour"], "stagePhotoNote": "Photo de référence du paysage de la zone : ce n’est pas forcément le point exact de la journée.", "skip": "Aller au contenu", "foldMore": "Afficher plus", "foldLess": "Afficher moins", "nav": ["Niveau", "Les étapes", "Le programme", "Prix", "Le guide", "Préparation", "Questions", "Documents"], "menu": "Ouvrir le menu", "close": "Fermer", "pdf": "Fiche du voyage", "langLabel": "Langue", "heroLabel": "BOLIVIE · CORDILLÈRE D’APOLOBAMBA", "heroTitle": "Apolobamba.<em>Le chemin nous rassemble.</em>", "heroText": "Six jours à pied entre Pelechuco et Charazani, sur des sentiers de bergers et par un col à plus de 5 000 m. Petit groupe, guide de montagne et guide local.", "heroCta": "Découvrir le trek", "heroSecond": "Voir le programme jour par jour", "heroDate": "Juin 2027 · meilleure période : de mi-juin à fin juillet", "photoNote": "Paysage réel d’Apolobamba", "facts": [["6", "jours de marche"], ["53 km", "de Pelechuco à Charazani"], ["5 032 m", "col Sunchulli, le point le plus haut"], ["11 + 2", "jours de programme et de réserve"]], "storyLabel": "02 / L’EXPÉRIENCE", "storyTitle": "Marcher loin.<br>Se sentir proches.", "storyLead": "Certains voyages se mesurent en kilomètres. Celui-ci se mesure aussi à ce que l’on apprend en chemin.", "storyText": "De Pelechuco à Charazani, le trek relie des vallées andines, des cols élevés et des pâturages au pied des glaciers d’Apolobamba. C’est un itinéraire exigeant et peu fréquenté, que nous parcourons sans hâte, en prenant le temps des savoirs locaux et de la vie de groupe.", "storyCaption": "Depuis le chemin de Charazani", "values": [["Un territoire vivant", "Nous lisons le paysage dans le respect des communautés et de leurs savoirs."], ["Un groupe qui marche ensemble", "Rythme partagé, regroupements et consignes claires."], ["Une préparation réfléchie", "Guide de montagne et guide local, avec un programme pensé pour bien s’acclimater."]], "routeLabel": "03 / LES ÉTAPES", "routeTitle": "Un chemin.<br>Six jours pour le vivre.", "routeIntro": "Nous marchons toujours de jour : départ à partir de 07 h 10 et arrivée au camp avant 16 h 40, heure bolivienne. Choisissez un jour pour en voir les données principales.", "stageLabel": "Jour", "distance": "Distance", "ascent": "Montée", "descent": "Descente", "duration": "11 jours / 10 nuits / 6 jours de marche, + 2 jours de réserve", "max": "Point le plus haut", "stageFocus": "La clé du jour", "routeNote": "53,4 km au total. Distances et dénivelés sont approximatifs et les horaires sont prévisionnels : l’itinéraire doit encore être reconnu sur le terrain avant l’ouverture des réservations. Près d’un tiers du chemin suit des pistes ouvertes par l’exploitation minière.", "stageNames": ["Pelechuco → Camp 1", "Camp 1 → Hilo Hilo", "Hilo Hilo → Camp 2", "Camp 2 → Incacancha", "Incacancha → Camp 3", "Camp 3 → Charazani"], "stageDescriptions": ["Nous quittons Pelechuco et montons régulièrement jusqu’au premier col, à 4 706 m, surtout par la piste minière qui le franchit. Nous descendons dans la vallée du Kotani et campons au fond de la vallée. Une journée pour trouver le rythme du groupe et voir comment chacun réagit à l’altitude.", "Courte journée facile, presque entièrement sur piste, jusqu’à la communauté d’Hilo Hilo. Nous dormons un peu plus bas que la veille et consacrons l’après-midi au repos, à l’hydratation et à la préparation du grand col du lendemain.", "La grande journée du trek. Nous remontons la vallée jusqu’au col Sunchulli, à plus de 5 000 m et près des glaciers, puis descendons camper dans la vallée de Sunchulli, ancienne zone minière.", "Trois cols enchaînés au-dessus de 4 500 m et la longue descente en lacets des Mil Curvas jusqu’à Incacancha, où nous campons près des cascades.", "Courte en distance, intense en dénivelé. Nous montons au col d’Akamani, sous la montagne sacrée des Kallawaya, passons l’apacheta de Tambillo et descendons au camp.", "Longue descente vers les vallées habitées : croisement de Curva, pont sur la rivière, une dernière remontée et arrivée à Charazani."], "stageFocusText": ["Plus de 1 000 m de montée soutenue et première nuit sous tente à 4 168 m.", "Journée de récupération : peu marcher, bien boire et bien dormir.", "Heure limite au col : 14 h 40. Avec de la neige dure ou de la glace au col, la journée ne se fait pas.", "La descente des Mil Curvas demande de l’attention si le terrain est humide ou gelé.", "La courte distance est trompeuse : 600 m de montée concentrée et la fatigue accumulée.", "Si nous sommes justes en temps au croisement de Curva, nous terminons là et faisons le dernier tronçon en véhicule."], "journeyLabel": "04 / LE PROGRAMME", "journeyTitle": "Onze jours,<br>pas à pas.", "journeyIntro": "Trois jours à La Paz pour s’acclimater, un jour de transfert, six jours de marche et un jour de retour.", "reserveTitle": "+ 2 jours de réserve", "reserveText": "Nous les utilisons s’il faut plus d’acclimatation, si la météo oblige à attendre ou en cas d’imprévu. Il faut donc disposer de 13 jours, plus les vols.", "methodLabel": "NOTRE MÉTHODE", "methodTitle": "La préparation se voit<br>à chaque pas.", "methodIntro": "La manière de guider fait partie de l’expérience. Préparer, observer, expliquer et apprendre pour s’améliorer.", "methodSteps": [["Avant de marcher", "Entretien préalable sur l’expérience et les attentes, réunion de groupe et information claire sur le niveau, le matériel et les changements possibles."], ["Chaque matin", "Briefing court : objectif du jour, conditions, eau, points de décision et état du groupe."], ["Pendant la journée", "Rythme de groupe, regroupements et explications sur le paysage et la culture aux endroits adaptés. Le jour du col Sunchulli, la priorité est de marcher."], ["Après le voyage", "Bilan quotidien avec le groupe, enquête anonyme et plan d’amélioration pour le départ suivant."]], "respectTitle": "Le territoire nous accompagne aussi.", "respectText": "Savoirs locaux, accords avec les communautés, respect des chemins et gestion responsable des déchets et de l’eau. Les visites et les photos de personnes se font avec permission.", "prepLabel": "06 / PRÉPARATION", "prepTitle": "Un bon sac.<br>Une bonne préparation.", "prepIntro": "Pour des personnes ayant l’expérience du trek sur plusieurs jours, capables d’enchaîner de longues journées et assez souples pour vivre avec les tentes, le froid et les changements de programme.", "gearTitle": "Votre liste de matériel", "gearHint": "Cochez ce que vous avez déjà prêt. Le matériel obligatoire est vérifié à La Paz avant le départ.", "gearCount": "éléments prêts", "reset": "Tout décocher", "saved": "Les coches sont enregistrées uniquement dans ce navigateur. Aucune donnée n’est envoyée.", "gearGroups": [["Obligatoire · vêtements et nuit", ["Chaussures de montagne déjà rodées", "Veste et pantalon imperméables", "Doudoune en duvet ou synthétique", "Gants, bonnet et tour de cou", "Sac de couchage confort −10 °C et matelas"]], ["Obligatoire · sac de journée", ["Sac à dos de 25–35 litres", "Gourdes pour 2–3 litres et traitement de l’eau", "Frontale avec piles ou batterie de rechange", "Lunettes catégorie 3–4 et crème solaire", "Passeport, assurance et médicaments personnels"]], ["Recommandé", ["Bâtons de marche", "Couches thermiques et chaussettes de rechange", "Nourriture de réserve pour le chemin", "Batterie externe", "Trousse de secours personnelle et sac pour les déchets"]]], "altitudeTitle": "L’altitude demande d’écouter.", "altitudeText": "Être en forme ne garantit pas de bien s’adapter. Nous passons cinq nuits au-dessus de 4 000 m et franchissons un col à plus de 5 000 m. Une consultation de médecine des voyages est nécessaire avant le départ.", "altitudePoints": ["Signalez au guide tout malaise.", "Avec des symptômes, on ne monte pas dormir plus haut.", "Si le groupe en a besoin, le programme est allongé ou modifié."], "priceLabel": "05 / PRIX DE RÉFÉRENCE", "priceTitle": "Savoir ce qu’il y a<br>derrière le voyage.", "priceNote": "Prix de référence avec réservation anticipée, pour un groupe de 8 personnes minimum et 13 maximum. C’est une estimation du projet, en attente des devis réels des prestataires locaux.", "perPerson": "par personne", "included": "Ce qui est inclus", "includeItems": ["Guide de montagne et guide local", "Transferts La Paz–Pelechuco et Charazani–La Paz (La Paz–Curva si le plan C est activé)", "Mules et portage", "Repas et hébergement pendant tout le programme", "Tentes et matériel collectif", "Assurance voyage et activité"], "excluded": "Ce qui n’est pas inclus", "excludeItems": ["Vols internationaux", "Équipement personnel : sac de couchage, matelas, vêtements et chaussures", "Dépenses personnelles et pourboires"], "priceDisclaimer": "Les réservations ne sont pas encore ouvertes. Dates, prix et services seront confirmés après la reconnaissance de l’itinéraire.", "priceCta": "Voir les conditions", "docsLabel": "08 / DOCUMENTS", "docsTitle": "Tout ce qu’il vous faut<br>pour préparer le voyage.", "docsIntro": "Des documents à lire tranquillement, à imprimer ou à garder sur le téléphone. Nous vous envoyons le dossier complet personnellement.", "docs": [["Fiche du voyage", "2 pages · PDF", "Niveau, conditions, programme jour par jour, point de rendez-vous, prix, réservation et annulation."], ["Préparation et matériel", "2 pages · PDF", "Santé et altitude, documents, ce que portent les mules et liste de matériel à cocher."], ["Plan d’entraînement", "12 semaines · PDF", "Que faire chaque semaine pour arriver prêt, avec renforcement et essais du matériel."], ["Dossier complet du voyage", "PDF · par WhatsApp", "Étapes point par point avec cartes et horaires, climat de juin, hébergements, préparation et conditions. Nous l’envoyons quand vous nous écrivez."]], "download": "Télécharger", "sourcesLabel": "Sources utilisées pour vérifier l’itinéraire", "sourcesText": "Le tracé repose sur un enregistrement GPS de 2012, mis à jour avec des informations récentes : récits et traces de randonneurs de 2022–2025, programmes d’opérateurs boliviens consultés en 2026 et OpenStreetMap, qui montre qu’environ un tiers du chemin est désormais une piste minière. Aucune de ces sources ne remplace la reconnaissance sur le terrain.", "sourcesButton": "Voir les sources", "sources": [["Trace GPS · Gallotrekk (Wikiloc)", "Enregistrement réel de 2012 : tracé, points de passage et temps de chaque étape."], ["Opérateur · Bolivian Mountain Guides", "Programme Pelechuco–Charazani : camps à Palca, Sunchulli et Jatunpampa ; col Sunchulli à 5 100 m."], ["Opérateur · Kaleidoscope Travel", "Camp au bord de la rivière Illo Illo et environ 6 h jusqu’à Sunchulli ; arrivée à Curva."], ["Opérateur · ZigZag Bolivia", "Environ 9 h de Palca à Sunchulli sans nuit intermédiaire ; camp à 4 500 m."], ["2022 · Expédition Colli", "Entretien avec des participants d’un trek de cinq jours sur le même couloir."], ["2022 · Trace d’un randonneur", "Trace publiée sur Wikiloc ; elle ne couvre pas le dernier tronçon jusqu’à Charazani."], ["2024 · Récit vidéo", "Vidéo du trek Pelechuco–Charazani, publiée en octobre 2024."], ["2025 · Accès à Pelechuco", "Récit du trajet en 4×4 jusqu’à Pelechuco."]], "faqLabel": "07 / AVANT DE DÉCIDER", "faqTitle": "Questions du chemin.", "faqs": [["Est-ce adapté comme premier trek ?", "Non. Il s’adresse à des randonneurs ayant l’expérience des treks de plusieurs jours, habitués aux longues journées et au camping. Avant de réserver, nous échangeons pour évaluer la préparation et les attentes."], ["Combien de jours me faut-il ?", "Le programme dure 11 jours : trois jours d’acclimatation à La Paz, un transfert, six jours de marche et un jour de retour. Nous ajoutons deux jours de réserve : il faut donc 13 jours, plus les vols."], ["Quelle est la journée la plus difficile ?", "Celle du col Sunchulli, le jour 7 : 11,4 km, environ 1 060 m de montée, 7 à 9 heures et un col à plus de 5 000 m. C’est pourquoi la veille est courte et nous dormons à Hilo Hilo."], ["Où dort-on ?", "Hôtel à La Paz, hébergement local simple à Pelechuco et Charazani et cinq nuits sous tente entre 4 000 et 4 700 m. Les nuits sont froides, souvent sous zéro."], ["Quelle est la meilleure période ?", "De mi-juin à fin juillet, au cœur de la saison sèche. Mai et septembre sont possibles mais plus incertains, et en août il y a eu de fortes chutes de neige au col Sunchulli. Nous proposons la seconde quinzaine de juin 2027."], ["Dois-je porter tous mes bagages ?", "Non. Des mules portent les tentes, la cuisine et les bagages ; dans la journée, vous portez un sac avec des vêtements chauds, de l’eau et de quoi manger."], ["L’eau est-elle potable ?", "Pas directement. Il y a des mines d’or dans la zone et traiter l’eau n’élimine pas les métaux : nous la prenons uniquement à des sources situées au-dessus des mines ou confirmées par la communauté, nous la traitons toujours et en portons une réserve sur le tronçon de Sunchulli."], ["Que se passe-t-il en cas de mauvais temps ou si quelqu’un ne va pas bien ?", "Le guide peut arrêter, raccourcir ou modifier une journée, et chaque journée a un plan B prêt. Nous avons deux jours de réserve, un itinéraire alternatif complet (le plan C, par Cañisaya et l’Akamani) et, sur la plus grande partie du parcours, un accès en véhicule si nécessaire. Avec de la neige dure ou de la glace sur les cols, on ne passe pas."], ["Ai-je besoin d’une assurance ?", "Le prix comprend une assurance voyage et activité couvrant le trekking jusqu’à 5 100 m, le secours et le rapatriement. Si vous en avez déjà une, vérifiez-la avec nous pour éviter les doublons."], ["L’itinéraire a-t-il été reconnu sur le terrain ?", "Pas encore. Le programme part d’une trace GPS de 2012 et a été comparé à des récits de randonneurs de 2022–2025, aux itinéraires d’opérateurs boliviens et à OpenStreetMap, où figurent déjà les pistes minières. Avant d’ouvrir les réservations, il faut reconnaître les cols, les camps, l’eau et le pont de la dernière journée."], ["Peut-on déjà réserver ?", "Pas encore. Ce site présente un projet académique de technicien sportif de montagne (TD2). Juin 2027 est une date proposée ; les réservations ouvriraient après validation de l’itinéraire, des services, des permis et des assurances."]], "endLabel": "LE PREMIER PAS", "endTitle": "Découvrez le voyage.<br>Préparez votre chemin.", "endText": "Consultez le programme complet et vérifiez s’il correspond à votre expérience.", "footerLine": "Montagne, territoire et chemin partagé.", "footerNote": "Projet académique TD2 · Izan Pimentel Pérez", "privacy": "Confidentialité", "terms": "Conditions du projet", "credits": "Photographie et cartographie", "privacyText": "Ce site ne collecte ni réservations ni données personnelles. La langue et les coches de la liste de matériel sont enregistrées uniquement dans votre navigateur et vous pouvez les effacer avec les commandes de la page. Les liens externes ont leurs propres conditions.", "termsText": "Andes Wild Trek est un projet académique de technicien sportif de montagne (TD2). Dates, prix et services sont indicatifs et ne constituent pas une offre ferme. Avant d’ouvrir les réservations, il faut valider l’itinéraire, les prestataires, les permis, les assurances et les conditions contractuelles.", "creditIntro": "Photographies documentaires d’Apolobamba et de Pelechuco, avec auteur et licence identifiés. Leur date ne certifie pas l’état actuel de l’itinéraire.", "mapNotice": "Les cartes utilisent les données OpenStreetMap et SRTM et le style OpenTopoMap, CC-BY-SA. Le tracé principal part d’un enregistrement GPS de 2012 ; les pistes et les itinéraires alternatifs viennent d’OpenStreetMap.", "dismiss": "Fermer la fenêtre", "notice": "", "dayWord": "Jour", "night": "Où dormons-nous", "schedule": "Horaires prévus", "scheduleText": "Départ {0} · arrivée {1}", "approx": "env.", "stageTabs": ["Camp 1", "Hilo Hilo", "Col Sunchulli", "Incacancha", "Akamani", "Charazani"], "itinCols": ["Jour", "Étape", "Ce que nous faisons", "Nuit"], "itinerary": [["1", "Arrivée à La Paz", "Accueil à l’aéroport d’El Alto, transfert à l’hôtel et réunion d’accueil à 19 h 00.", "Hôtel · 3 650 m"], ["2", "Adaptation à La Paz", "Promenade tranquille en ville, hydratation et repos.", "Hôtel · 3 650 m"], ["3", "Acclimatation et préparation", "Marche modérée, vérification du matériel et réunion de préparation.", "Hôtel · 3 650 m"], ["4", "La Paz → Pelechuco", "Transfert en 4×4 par le lac Titicaca et l’altiplano d’Ulla Ulla. Environ 12 heures.", "Hébergement local · 3 660 m"], ["5", "Pelechuco → Camp 1", "9,7 km · +1 047 m · 6–8 h", "Tente · 4 168 m"], ["6", "Camp 1 → Hilo Hilo", "4,2 km · 2–3 h · après-midi de repos", "Tente · 4 010 m"], ["7", "Hilo Hilo → col Sunchulli → Camp 2", "11,4 km · +1 062 m · 7–9 h", "Tente · 4 500–4 700 m"], ["8", "Camp 2 → Incacancha", "8,3 km · −867 m · 5–7 h", "Tente · 4 060 m"], ["9", "Incacancha → Camp 3", "4,1 km · +602 m · 4–6 h", "Tente · 4 171 m"], ["10", "Camp 3 → Charazani", "15,8 km · −1 473 m · 8–9 h 30", "Hébergement local · 3 195 m"], ["11", "Charazani → La Paz", "Retour en véhicule (7–8 heures) et au revoir.", "Fin du voyage"]], "priceAmount": "2 700", "hubLabel": "LE PROJET BLOC PAR BLOC", "hubTitle": "Le projet,<br>bloc par bloc.", "hubIntro": "Les six blocs du projet, en PDF (en catalan). Vous pouvez les ouvrir, les télécharger ou chercher dans leur contenu.", "hubFull": "Projet complet", "hubChanges": "Changements et décisions en attente", "hubSearch": "Chercher dans le projet", "hubSearchPh": "Budget, permis, checklist, Sunchulli…", "hubPresent": "Mode présentation", "hubPresentOff": "Quitter le mode présentation", "hubCount": "{0} sur 6 blocs", "hubPages": "pages", "hubMeta": "PDF · catalan", "hubOpen": "Ouvrir le PDF", "hubDownload": "Télécharger", "hubRead": "Lire le texte ici", "hubNav": "Blocs du projet", "igLabel": "INSTAGRAM / MAQUETTE ACADÉMIQUE", "igText": "Six publications d’exemple de la campagne de huit semaines. C’est une maquette du plan marketing, pas un compte réel.", "igCta": "Voir le plan marketing", "igPosts": ["Six jours, un seul chemin. Présentation du trek.", "5 032 m : le jour du col Sunchulli.", "Pelechuco, là où tout commence.", "Qu’y a-t-il dans mon sac ? La liste est sur le site.", "Petit groupe : de 8 à 13 personnes.", "Trois jours à La Paz avant de marcher."], "igCredit": "Photos : Realnif, Raullike et Das Morton · Wikimedia Commons · CC BY-SA 4.0.", "treballNav": "Projet TD2", "condLabel": "CONDITIONS DU VOYAGE", "condTitle": "Des conditions claires dès le départ.", "conds": [["Groupe minimum et maximum", "Le voyage part avec 8 personnes minimum et 13 maximum. Si le minimum n’est pas atteint, nous vous prévenons au moins 30 jours avant et vous remboursons 100 % des sommes versées sous 14 jours, ou nous gardons votre place pour une autre date."], ["Ce que comprend le prix", "Guide de montagne et guide local (de 10 à 13 personnes, un renfort local s’ajoute), transferts en 4×4 du programme, mules, tous les repas et hébergements du programme, tentes et matériel collectif, et assurance voyage et activité couvrant le trekking jusqu’à 5 100 m, le secours et le rapatriement."], ["Jours de réserve", "Les deux jours de réserve sont inclus dans le prix. S’ils sont utilisés, il n’y a pas de coût supplémentaire. Si une situation exigeait plus de jours, nous vous informerions du nouveau programme et de son coût avant de continuer."], ["Conditions de participation", "Expérience du trek sur plusieurs jours, entretien préalable avec le guide, consultation de médecine des voyages et passeport valide. Il faut disposer de 13 jours, plus les vols."], ["Comment réserver", "À l’ouverture des réservations : entretien préalable, dossier complet et contrat de voyage à forfait. La place est confirmée avec un acompte de 30 % et le solde se paie 45 jours avant le départ. Prix : 2 700 € jusqu’à 90 jours avant et 2 850 € ensuite. Andes Wild Trek agit en tant qu’organisateur du voyage."], ["Changements pendant le voyage", "Le guide peut modifier, raccourcir ou arrêter une journée pour la sécurité, la météo ou l’état du groupe. Chaque journée a un plan B : la dernière peut se terminer à Curva en véhicule et, si nécessaire, l’évacuation se fait par les pistes. Ces changements n’ont pas de coût supplémentaire."], ["Si le plan C est activé", "Si, avant le départ, le col Sunchulli n’est pas praticable ou la zone minière le déconseille, le trek passe par Cañisaya et le chemin de l’Akamani. Le programme commence par un transfert de La Paz à Curva et dure neuf jours. Le prix ne change pas : guides, mules, repas, hébergements et transferts sont maintenus, et les deux jours économisés s’ajoutent aux jours de réserve. Nous vous l’expliquons et vous l’acceptez avant de quitter La Paz."], ["Si vous annulez", "Frais sur le prix total : 10 % à plus de 90 jours, 25 % de 90 à 61, 50 % de 60 à 31, 75 % de 30 à 15 et 100 % à moins de 15 jours ou en cas de non-présentation. Vous pouvez céder votre place à une personne qui remplit les conditions. Sans frais en cas de circonstances exceptionnelles et inévitables à destination. Conditions à valider juridiquement."], ["Groupe privé", "Pour les groupes de 8 à 13 personnes, avec des dates au choix pendant la saison (du 15 juin au 31 juillet) et un devis sur mesure."]], "condNote": "Les réservations ne sont pas encore ouvertes. Dates, prix et conditions définitifs seront confirmés après la reconnaissance de l’itinéraire.", "stageDossier": "Les points de passage, les cartes et les horaires détaillés de chaque journée sont dans le dossier complet, que nous vous envoyons quand vous nous écrivez.", "docRequest": "Le demander", "seasonLabel": "QUAND PARTIR", "planTitle": "Si le chemin ne laisse pas passer", "planText": "Chaque journée a un plan B prêt et il existe un itinéraire alternatif complet. S’il faut changer, le guide décide en pensant à la sécurité du groupe.", "planItems": [["Col Sunchulli (5 032 m)", "Il y a une heure limite : 14 h 40. Si nous n’y sommes pas à temps, s’il y a de la neige dure ou de la glace ou si le temps est mauvais, nous revenons à Hilo Hilo et utilisons un jour de réserve."], ["Descente des Mil Curvas", "Avec de la neige, de la glace ou peu de visibilité, nous n’y entrons pas. Il existe une descente alternative plus longue et moins raide, ou nous pouvons dormir dans la communauté de Quellwa Cota."], ["Fin du trek", "Si nous sommes justes en temps, nous terminons à Curva et continuons en véhicule jusqu’à Charazani."], ["Plan C · par l’Akamani", "Si le col Sunchulli n’est pas praticable ou si la zone minière le déconseille, nous faisons le trek par Cañisaya et le chemin de l’Akamani jusqu’à Charazani : quatre jours, 35 km et un point culminant à 4 661 m."], ["Pistes et évacuation", "Près d’un tiers du chemin suit des pistes minières. En contrepartie, sur la plus grande partie du parcours, un véhicule peut arriver s’il faut évacuer quelqu’un."]], "tw": {"title": "Projet TD2 · Andes Wild Trek · Apolobamba", "nav": ["Le voyage", "Le projet", "Plans B et C", "Blocs", "Outils", "Évaluation", "Sources"], "eyebrow": "PROJET ACADÉMIQUE · TECHNICIEN SPORTIF EN MOYENNE MONTAGNE", "h1": "Andes Wild Trek<br>Apolobamba", "lead": "Projet de création d’une entreprise de guidage et d’un trek de six jours entre Pelechuco et Charazani, en Bolivie.", "meta": "Izan Pimentel Pérez · 24 novembre 2026 · Documents en catalan", "full": "Projet complet (PDF)", "word": "Version modifiable (Word)", "back": "Voir le site du voyage", "keyLabel": "LE PROJET EN QUATRE POINTS", "keys": [["Entreprise", "Organisateur de voyages à forfait basé en Catalogne, avec un opérateur local en Bolivie."], ["Programme", "11 jours et 2 de réserve : 3 d’acclimatation, 1 de transfert, 6 de marche et 1 de retour. Meilleure période : de mi-juin à fin juillet."], ["Budget", "2 700 € par personne avec un minimum de 8 et un maximum de 13 ; marge visée de 20 %."], ["Étape suivante", "Reconnaissance de terrain, devis locaux et permis avant la commercialisation."]], "present": "Présentations", "presentOff": "Quitter le mode présentation", "toolsLabel": "OUTILS DU GUIDE ET ANNEXES", "toolsTitle": "Pour l’appliquer<br>sur le terrain.", "tools": [["Formulaires opérationnels", "10 pages · PDF", "Checklist quotidienne, enquête, auto-évaluation, rapport d’amélioration et dossier d’ouverture.", "dossiers/Apolobamba_Formularis_Operatius.pdf"], ["Enquête client", "1 page · PDF · ca, es, en, fr", "Enquête de satisfaction anonyme remise à la fin du voyage, dans la langue du client.", "dossiers/Enquesta_Satisfaccio_FR.pdf"], ["Atlas cartographique", "11 planches · PDF A3", "Carte générale avec les plans B et C, les six jours de marche et les quatre étapes du plan C, avec profil, points de passage, itinéraires d’évacuation et GPX.", "dossiers/Apolobamba_Atles_Cartografic_A3.pdf"], ["Flyer avec QR", "Image · JPG", "Support du plan marketing avec une vraie photo ; le QR ouvre le site du voyage.", "assets/flyer.jpg"], ["Application du guide", "Mobile · hors ligne", "Horaire et lumière en temps réel, GPS sur le tracé, heures limites et décisions, carte hors ligne, plans B et C, météo par point, SOS avec coordonnées, listes et GPX.", "guia/"], ["Dossier complet du client", "15 pages · PDF", "Document envoyé au client quand il prend contact : étapes point par point, cartes, climat et conditions.", "dossiers/client/Dossier_Voyage_FR.pdf"]], "avalLabel": "OUTILS D’ÉVALUATION", "avalTitle": "Évaluer pour de vrai,<br>pas seulement sur le papier.", "avalIntro": "L’enquête client, la checklist quotidienne et l’auto-évaluation du guide de l’annexe A, transformées en outils utilisables. L’enquête est un formulaire anonyme en quatre langues ; la checklist et l’auto-évaluation fonctionnent dans l’application du guide, hors ligne, et s’exportent en CSV ou PDF.", "avalQr": "Scannez pour ouvrir l’enquête", "aval": [["Enquête client en ligne", "Formulaire Google · anonyme · ca, es, en, fr", "Le client choisit sa langue et répond depuis son téléphone à la fin du voyage (environ 3 minutes). Ni nom ni e-mail ; les réponses vont dans un tableur tenu par le responsable.", "https://docs.google.com/forms/d/e/1FAIpQLScnXaBFRML574r8K5PI5J7VZYa5B6C28ZPedfOIt_a5luli2g/viewform"], ["Checklist quotidienne du guide", "Application du guide · hors ligne", "Douze vérifications avant le départ (Oui / Non / NA), décision de départ et registre de la journée. Enregistrée sur le téléphone et exportée en CSV ou PDF.", "guia/?aval=check"], ["Auto-évaluation du guide", "Application du guide · hors ligne", "Dix aspects notés de 1 à 5 avec un fait observable, moyenne et clôture avec l’action prioritaire. Dans les 72 heures suivant le service.", "guia/?aval=auto"], ["QR de l’enquête", "Image · SVG", "À imprimer dans le carnet de route ou à montrer depuis l’application le dernier jour, pour que chaque client l’ouvre sur son téléphone.", "assets/enquesta-qr.svg"]], "open": "Ouvrir", "sourcesLabel": "SOURCES", "sourcesTitle": "Vérification de l’itinéraire", "mapLabel": "CARTE DU PROJET", "mapTitle": "Comment les pièces s’assemblent.", "map": [["Entreprise et marché", [["Environnement professionnel", "Modèle d’agence, public et SWOT", "empresa"], ["Réglementation", "Diplôme, contrat et assurances", "normativa"], ["Marketing", "Message, campagne et flyer", "marketing"]]], ["Produit", [["Programme", "11 + 2 jours, six jours de marche et acclimatation", "empresa"], ["Budget", "2 700 € avec un minimum de 8", "empresa"], ["Fiche client", "Ce que reçoivent les participants", "client"]]], ["Opérations", [["Méthodologie", "Conduite, dynamiques de groupe et évaluation", "metodologia"], ["Fiche du guide", "Horaires, points de décision et cartes", "guia"], ["Formulaires", "Checklist, enquête et dossier", "eines"]]]], "mapBase": "Tout le projet repose sur deux limites : les compétences du TD2 au col Sunchulli et la reconnaissance de terrain avant la vente.", "planLabel": "SAISON, PLANS B ET PLAN C", "planHeading": "Quand partir<br>et que faire si l’on ne peut pas passer.", "planIntro": "Révision du 17/11/2026 avec des récits d’alpinistes, des opérateurs, l’ABC (routes boliviennes) et OpenStreetMap. Chaque journée a des plans B et des itinéraires d’évacuation, et le plan C est un itinéraire complet par l’Akamani.", "planBTitle": "Plans B par journée", "planCTitle": "Fiches techniques du plan C", "roadsNote": "Consulté le", "colsC": ["Étape", "Jour", "Km", "Dénivelé", "Max.", "Durée", "Horaires", "Nuit"], "gpxB": "Télécharger le plan B du jour", "gpxC": "GPX du plan C", "gpxMain": "GPX de l’itinéraire principal"}, "levelLabel": "01 / NIVEAU ET CONDITIONS", "levelTitle": "Est-ce pour vous ?<br>Vérifiez d’abord.", "levelIntro": "Quatre indicateurs pour voir d’un coup d’œil ce que demande le trek. La difficulté technique est faible : ce qui le rend exigeant, c’est sa durée, l’altitude et l’isolement.", "levels": [["Exigence physique", 3, "Élevée", "Journées jusqu’à 9 h 30, six jours d’affilée, et près de 1 500 m de descente le dernier jour."], ["Difficulté technique", 1, "Faible", "Sentiers et pistes, sans passage d’escalade. Ni crampons ni piolet : avec de la neige dure ou de la glace, on ne passe pas."], ["Altitude", 4, "Très élevée", "Cinq nuits au-dessus de 4 000 m et un col à 5 032 m. L’acclimatation est nécessaire et chacun s’adapte différemment."], ["Isolement", 3, "Élevé", "Pas de réseau mobile. Une évacuation peut prendre des heures ou une journée, par piste ou à pied."]], "reqTitle": "Conditions de participation", "reqs": ["Avoir déjà fait au moins un trek de 3 jours ou plus avec sac à dos et nuits dehors.", "Pouvoir marcher 8–9 heures avec environ 1 000 m de dénivelé et recommencer le lendemain.", "Consultation de médecine des voyages sans contre-indication à l’altitude.", "Passeport valide et 13 jours libres, plus les vols.", "Accepter les décisions du guide sur le rythme, les retraites et les plans alternatifs."], "meetTitle": "Point de rendez-vous", "meetText": "Jour 1, aéroport international d’El Alto (La Paz, LPB) : nous vous accueillons à l’arrivée de votre vol et vous conduisons à l’hôtel. Réunion d’accueil à 19 h 00 à l’hôtel. Le service se termine le jour 11 dans l’après-midi, à l’arrivée à La Paz.", "earlyLabel": "Réservation anticipée · jusqu’à 90 jours avant", "stdLabel": "À moins de 90 jours du départ", "priceStd": "2 850", "guarantee": ["Garantie de départ", "Si le groupe n’atteint pas 8 personnes, nous vous prévenons au moins 30 jours avant et vous remboursons 100 % des sommes versées sous 14 jours, ou nous gardons votre place pour une autre date, comme vous préférez."], "extrasTitle": "Suppléments optionnels", "extras": [["Chambre individuelle (hôtels de La Paz, Pelechuco et Charazani)", "Prix à confirmer"], ["Tente individuelle", "Prix à confirmer"], ["Location d’un sac de couchage −10 °C", "Prix à confirmer"], ["Nuits à La Paz après le jour 11 si les jours de réserve ne sont pas utilisés", "À votre charge ; nous vous aidons à réserver"]], "bookTitle": "Comment réserver", "bookSteps": [["Écrivez-nous", "Par WhatsApp, avec la date qui vous intéresse et votre expérience."], ["Entretien préalable", "Nous parlons de votre expérience, de votre santé et de vos attentes pour voir si le trek vous convient."], ["Dossier et contrat", "Nous vous envoyons le dossier complet et le contrat de voyage à forfait."], ["Acompte et confirmation", "Vous versez un acompte de 30 % et votre place est confirmée. Le solde, 45 jours avant le départ."]], "cancelTitle": "Si vous devez annuler", "cancelCols": ["Quand vous annulez", "Frais sur le prix total"], "cancelRows": [["Plus de 90 jours avant", "10 %"], ["De 90 à 61 jours", "25 %"], ["De 60 à 31 jours", "50 %"], ["De 30 à 15 jours", "75 %"], ["Moins de 15 jours ou non-présentation", "100 %"]], "cancelNotes": ["Vous pouvez céder votre place à une personne qui remplit les conditions ; vous ne payez que les frais du changement.", "Sans frais si des circonstances exceptionnelles et inévitables à destination empêchent le voyage.", "Nous recommandons une assurance annulation, non incluse."], "privateTitle": "Groupe privé", "privateText": "Si vous êtes un groupe de 8 à 13 personnes, vous pouvez choisir vos dates pendant la saison (du 15 juin au 31 juillet). Nous établissons un devis sur mesure.", "gearOrgTitle": "Fourni par l’organisation", "gearOrg": ["Tentes, cuisine et tous les repas du trek", "Mules pour les bagages", "Trousse de secours du groupe et oxymètre", "Communicateur satellite", "Matériel de sécurité du groupe"], "levelWord": "Niveau"}};
