window.PLANS = {"season": {"months": ["no", "no", "no", "no", "ok", "best", "best", "risk", "ok", "no", "no", "no"], "ca": {"title": "Quan fer la travessa", "window": "Finestra recomanada: del 15 de juny al 31 de juliol", "proposal": "Sortida proposada: segona quinzena de juny de 2027", "monthNames": ["Gen", "Feb", "Mar", "Abr", "Mai", "Jun", "Jul", "Ago", "Set", "Oct", "Nov", "Des"], "legend": {"best": "Recomanat", "ok": "Possible, amb més incertesa", "risk": "Possible, amb risc de nevades fortes", "no": "No recomanat"}, "reasons": [["Juny i juliol", "És el cor de l’estació seca: el temps és més estable, els rius baixen amb menys cabal i les carreteres del nord de La Paz estan obertes. Les nits són les més fredes de l’any."], ["Maig i setembre", "Possibles, però amb més incertesa: al maig encara poden quedar pluges i rius alts; al setembre augmenten les tempestes de tarda. Els operadors bolivians ofereixen la ruta de maig a setembre."], ["Agost", "Hi ha hagut nevades fortes a la zona del pas Sunchulli: uns 60 cm el 10 i 11 d’agost de 1993, amb els passos tancats, i nevades breus entre l’agost i el setembre de 2019. Només amb previsió molt estable i dies de reserva."], ["De desembre a abril", "Estació de pluges. La carretera Charazani–Apolo es va tallar del 9 al 19 de febrer de 2025 i hi va haver esllavissades al gener i al març de 2026."]]}, "es": {"title": "Cuándo hacer la travesía", "window": "Ventana recomendada: del 15 de junio al 31 de julio", "proposal": "Salida propuesta: segunda quincena de junio de 2027", "monthNames": ["Ene", "Feb", "Mar", "Abr", "May", "Jun", "Jul", "Ago", "Sep", "Oct", "Nov", "Dic"], "legend": {"best": "Recomendado", "ok": "Posible, con más incertidumbre", "risk": "Posible, con riesgo de nevadas fuertes", "no": "No recomendado"}, "reasons": [["Junio y julio", "Es el corazón de la estación seca: el tiempo es más estable, los ríos bajan con menos caudal y las carreteras del norte de La Paz están abiertas. Las noches son las más frías del año."], ["Mayo y septiembre", "Posibles, pero con más incertidumbre: en mayo aún pueden quedar lluvias y ríos altos; en septiembre aumentan las tormentas de tarde. Los operadores bolivianos ofrecen la ruta de mayo a septiembre."], ["Agosto", "Ha habido nevadas fuertes en la zona del paso Sunchulli: unos 60 cm el 10 y 11 de agosto de 1993, con los pasos cerrados, y nevadas breves entre agosto y septiembre de 2019. Solo con previsión muy estable y días de reserva."], ["De diciembre a abril", "Estación de lluvias. La carretera Charazani–Apolo se cortó del 9 al 19 de febrero de 2025 y hubo derrumbes en enero y marzo de 2026."]]}, "en": {"title": "When to do the trek", "window": "Recommended window: 15 June to 31 July", "proposal": "Proposed departure: second half of June 2027", "monthNames": ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"], "legend": {"best": "Recommended", "ok": "Possible, less certain", "risk": "Possible, risk of heavy snow", "no": "Not recommended"}, "reasons": [["June and July", "The heart of the dry season: the weather is more stable, rivers carry less water and the roads in northern La Paz are open. Nights are the coldest of the year."], ["May and September", "Possible but less certain: in May there may still be rain and high rivers; in September afternoon storms increase. Bolivian operators offer the route from May to September."], ["August", "There has been heavy snow around the Sunchulli Pass: about 60 cm on 10 and 11 August 1993, with the passes closed, and short snowfalls between August and September 2019. Only with a very stable forecast and reserve days."], ["December to April", "Rainy season. The Charazani–Apolo road was cut from 9 to 19 February 2025 and there were landslides in January and March 2026."]]}, "fr": {"title": "Quand faire le trek", "window": "Période recommandée : du 15 juin au 31 juillet", "proposal": "Départ proposé : seconde quinzaine de juin 2027", "monthNames": ["Jan", "Fév", "Mar", "Avr", "Mai", "Juin", "Juil", "Août", "Sep", "Oct", "Nov", "Déc"], "legend": {"best": "Recommandé", "ok": "Possible, plus incertain", "risk": "Possible, risque de fortes chutes de neige", "no": "Déconseillé"}, "reasons": [["Juin et juillet", "Le cœur de la saison sèche : le temps est plus stable, les rivières ont moins de débit et les routes du nord de La Paz sont ouvertes. Les nuits sont les plus froides de l’année."], ["Mai et septembre", "Possibles mais plus incertains : en mai il peut encore pleuvoir et les rivières être hautes ; en septembre les orages d’après-midi augmentent. Les opérateurs boliviens proposent l’itinéraire de mai à septembre."], ["Août", "Il y a eu de fortes chutes de neige autour du col Sunchulli : environ 60 cm les 10 et 11 août 1993, cols fermés, et de brèves chutes de neige entre août et septembre 2019. Seulement avec une prévision très stable et des jours de réserve."], ["De décembre à avril", "Saison des pluies. La route Charazani–Apolo a été coupée du 9 au 19 février 2025 et il y a eu des glissements de terrain en janvier et mars 2026."]]}}, "b": [{"day": 5, "ca": [["Abans del Pas 1", "Si el grup no està bé o el temps empitjora, tornar a Pelechuco pel mateix camí (6,4 km com a màxim)."], ["Evacuació en vehicle", "Uns 6 dels 9,7 km van per la pista Pelechuco–Hilo Hilo, que creua el Pas 1 (pas de Katantika): un 4×4 des de Pelechuco pot arribar al pas i al Campament 1."], ["A la nit", "Amb símptomes d’altitud al Campament 1 (4.168 m), baixar a Pelechuco (3.660 m) per la pista."]], "es": [["Antes del Paso 1", "Si el grupo no está bien o el tiempo empeora, volver a Pelechuco por el mismo camino (6,4 km como máximo)."], ["Evacuación en vehículo", "Unos 6 de los 9,7 km van por la pista Pelechuco–Hilo Hilo, que cruza el Paso 1 (paso de Katantika): un 4×4 desde Pelechuco puede llegar al paso y al Campamento 1."], ["Por la noche", "Con síntomas de altitud en el Campamento 1 (4.168 m), bajar a Pelechuco (3.660 m) por la pista."]], "en": [["Before Pass 1", "If the group is not well or the weather worsens, return to Pelechuco on the same path (6.4 km at most)."], ["Vehicle evacuation", "About 6 of the 9.7 km follow the Pelechuco–Hilo Hilo track, which crosses Pass 1 (Katantika pass): a 4×4 from Pelechuco can reach the pass and Camp 1."], ["At night", "With altitude symptoms at Camp 1 (4,168 m), descend to Pelechuco (3,660 m) by the track."]], "fr": [["Avant le col 1", "Si le groupe ne va pas bien ou si le temps se dégrade, revenir à Pelechuco par le même chemin (6,4 km au maximum)."], ["Évacuation en véhicule", "Environ 6 des 9,7 km suivent la piste Pelechuco–Hilo Hilo, qui franchit le col 1 (col de Katantika) : un 4×4 depuis Pelechuco peut atteindre le col et le camp 1."], ["La nuit", "Avec des symptômes d’altitude au camp 1 (4 168 m), descendre à Pelechuco (3 660 m) par la piste."]]}, {"day": 6, "ca": [["Tota la jornada", "Gairebé tota la jornada va per la pista. Hilo Hilo és un poble amb escola i pista a Pelechuco (uns 20 km): punt d’evacuació en vehicle."], ["Més aclimatació", "Si algú ho necessita, es fa servir un dia de reserva a Hilo Hilo abans del pas Sunchulli."]], "es": [["Toda la jornada", "Casi toda la jornada va por la pista. Hilo Hilo es un pueblo con escuela y pista a Pelechuco (unos 20 km): punto de evacuación en vehículo."], ["Más aclimatación", "Si alguien lo necesita, se usa un día de reserva en Hilo Hilo antes del paso Sunchulli."]], "en": [["The whole day", "Almost the whole day follows the track. Hilo Hilo is a village with a school and a track to Pelechuco (about 20 km): a vehicle evacuation point."], ["More acclimatisation", "If someone needs it, a reserve day is used in Hilo Hilo before the Sunchulli Pass."]], "fr": [["Toute la journée", "Presque toute la journée suit la piste. Hilo Hilo est un village avec une école et une piste vers Pelechuco (environ 20 km) : point d’évacuation en véhicule."], ["Plus d’acclimatation", "Si quelqu’un en a besoin, on utilise un jour de réserve à Hilo Hilo avant le col Sunchulli."]]}, {"day": 7, "ca": [["Abans de les 10.10", "Amb retard, símptomes o previsió desfavorable al primer control: tornar a Hilo Hilo."], ["Hora límit al pas: 14.40", "Si el grup no hi és a l’hora, mitja volta cap a Hilo Hilo. La pista Hilo Hilo–Sorapata puja per la vall fins al pas: un 4×4 hi pot arribar per evacuar."], ["Pas tancat", "Amb neu dura o gel no es creua: dia de reserva a Hilo Hilo. Si continua tancat, retirada a Pelechuco en vehicle i trasllat a Charazani per fer el pla C."], ["Després del pas", "Sunchully (comunitat minera, 4.540 m) és a 2,6 km del Campament 2 per pista, amb sortida en vehicle cap a Sorapata (7,4 km) i, pel pas, cap a Hilo Hilo i Pelechuco (uns 38 km). L’evacuació en vehicle s’acorda abans de sortir."], ["Aigua", "No s’agafa aigua del riu Sunchulli ni de cap curs per sota de les mines. Sortir d’Agua buena 3 amb 2–3 litres per persona per a la tarda i la nit."]], "es": [["Antes de las 10:10", "Con retraso, síntomas o previsión desfavorable en el primer control: volver a Hilo Hilo."], ["Hora límite en el paso: 14:40", "Si el grupo no ha llegado a esa hora, media vuelta hacia Hilo Hilo. La pista Hilo Hilo–Sorapata sube por el valle hasta el paso: un 4×4 puede llegar para evacuar."], ["Paso cerrado", "Con nieve dura o hielo no se cruza: día de reserva en Hilo Hilo. Si sigue cerrado, retirada a Pelechuco en vehículo y traslado a Charazani para hacer el plan C."], ["Después del paso", "Sunchully (comunidad minera, 4.540 m) está a 2,6 km del Campamento 2 por pista, con salida en vehículo hacia Sorapata (7,4 km) y, por el paso, hacia Hilo Hilo y Pelechuco (unos 38 km). La evacuación en vehículo se acuerda antes de salir."], ["Agua", "No se coge agua del río Sunchulli ni de ningún curso por debajo de las minas. Salir de Agua buena 3 con 2–3 litros por persona para la tarde y la noche."]], "en": [["Before 10:10", "If late, with symptoms or a poor forecast at the first control: return to Hilo Hilo."], ["Cut-off at the pass: 14:40", "If the group is not there by then, turn back to Hilo Hilo. The Hilo Hilo–Sorapata track climbs the valley to the pass: a 4×4 can reach it for an evacuation."], ["Pass closed", "With hard snow or ice we do not cross: reserve day in Hilo Hilo. If it stays closed, withdraw to Pelechuco by vehicle and transfer to Charazani to do plan C."], ["After the pass", "Sunchully (mining community, 4,540 m) is 2.6 km from Camp 2 by track, with a vehicle exit towards Sorapata (7.4 km) and, over the pass, towards Hilo Hilo and Pelechuco (about 38 km). Vehicle evacuation is agreed before setting off."], ["Water", "No water from the Sunchulli river or any stream below the mines. Leave Agua buena 3 with 2–3 litres per person for the afternoon and night."]], "fr": [["Avant 10 h 10", "En cas de retard, de symptômes ou de prévision défavorable au premier contrôle : retour à Hilo Hilo."], ["Heure limite au col : 14 h 40", "Si le groupe n’y est pas à l’heure, demi-tour vers Hilo Hilo. La piste Hilo Hilo–Sorapata remonte la vallée jusqu’au col : un 4×4 peut y arriver pour évacuer."], ["Col fermé", "Avec de la neige dure ou de la glace, on ne passe pas : jour de réserve à Hilo Hilo. S’il reste fermé, repli sur Pelechuco en véhicule et transfert à Charazani pour faire le plan C."], ["Après le col", "Sunchully (communauté minière, 4 540 m) est à 2,6 km du camp 2 par la piste, avec une sortie en véhicule vers Sorapata (7,4 km) et, par le col, vers Hilo Hilo et Pelechuco (environ 38 km). L’évacuation en véhicule se convient avant le départ."], ["Eau", "Pas d’eau de la rivière Sunchulli ni d’aucun cours d’eau en aval des mines. Partir d’Agua buena 3 avec 2–3 litres par personne pour l’après-midi et la nuit."]]}, {"day": 8, "ca": [["Pla B1 · baixada alternativa", "Amb neu, gel, roca mullada o poca visibilitat no s’entra a les Mil Corbes (500 m de baixada en 1,2 km). Alternativa: des del Pas 5 baixar cap al sud fins al riu Akamani (≈3.950 m) i remuntar 0,8 km fins a Incacancha. Són 2,9 km i −600/+135 m, més llarga i amb menys pendent; té un tram d’uns 200 m sense cartografiar que cal reconèixer. És la baixada «menys dreta però menys directa» que indicaven els guardaparcs el 2019."], ["Pla B2 · no baixar", "Si cap de les dues baixades és segura: anar a Quellwa Cota (comunitat, 4.460 m, a 1 km del Pas 5) i acampar-hi amb permís, o evacuar en vehicle per la pista Quellwa Cota–Sunchully (8,3 km)."], ["Pla B3 · tornar", "Abans del Pas 4, tornar al Campament 2 pel mateix camí."]], "es": [["Plan B1 · bajada alternativa", "Con nieve, hielo, roca mojada o poca visibilidad no se entra en las Mil Curvas (500 m de bajada en 1,2 km). Alternativa: desde el Paso 5 bajar hacia el sur hasta el río Akamani (≈3.950 m) y remontar 0,8 km hasta Incacancha. Son 2,9 km y −600/+135 m, más larga y con menos pendiente; tiene un tramo de unos 200 m sin cartografiar que hay que reconocer. Es la bajada «menos empinada pero menos directa» que indicaban los guardaparques en 2019."], ["Plan B2 · no bajar", "Si ninguna de las dos bajadas es segura: ir a Quellwa Cota (comunidad, 4.460 m, a 1 km del Paso 5) y acampar allí con permiso, o evacuar en vehículo por la pista Quellwa Cota–Sunchully (8,3 km)."], ["Plan B3 · volver", "Antes del Paso 4, volver al Campamento 2 por el mismo camino."]], "en": [["Plan B1 · alternative descent", "With snow, ice, wet rock or poor visibility we do not enter the Mil Curvas (500 m of descent in 1.2 km). Alternative: from Pass 5 descend south to the Akamani river (≈3,950 m) and climb 0.8 km back to Incacancha. It is 2.9 km and −600/+135 m, longer and less steep; it has an unmapped stretch of about 200 m that must be checked. It is the “less steep but less direct” descent the park rangers pointed out in 2019."], ["Plan B2 · do not descend", "If neither descent is safe: go to Quellwa Cota (community, 4,460 m, 1 km from Pass 5) and camp there with permission, or evacuate by vehicle on the Quellwa Cota–Sunchully track (8.3 km)."], ["Plan B3 · turn back", "Before Pass 4, return to Camp 2 on the same path."]], "fr": [["Plan B1 · descente alternative", "Avec de la neige, de la glace, du rocher mouillé ou peu de visibilité, on n’entre pas dans les Mil Curvas (500 m de descente en 1,2 km). Alternative : depuis le col 5, descendre vers le sud jusqu’à la rivière Akamani (≈3 950 m) et remonter 0,8 km jusqu’à Incacancha. Soit 2,9 km et −600/+135 m, plus long et moins raide ; il comporte un tronçon d’environ 200 m non cartographié à reconnaître. C’est la descente « moins raide mais moins directe » indiquée par les gardes du parc en 2019."], ["Plan B2 · ne pas descendre", "Si aucune des deux descentes n’est sûre : aller à Quellwa Cota (communauté, 4 460 m, à 1 km du col 5) et y camper avec autorisation, ou évacuer en véhicule par la piste Quellwa Cota–Sunchully (8,3 km)."], ["Plan B3 · faire demi-tour", "Avant le col 4, revenir au camp 2 par le même chemin."]]}, {"day": 9, "ca": [["Abans del Pas d’Akamani", "Amb tempesta, mala visibilitat, neu o gel previstos als colls: no començar la pujada i quedar-se a Incacancha (dia de reserva)."], ["Sortida per l’est", "Si els colls no són practicables, sortir pel camí de l’Akamani cap a Huayrapata i la carretera RN16 (etapes C3 i C4 del pla C): 19,4 km en dues jornades, sense passar de 4.060 m."], ["Després del pas", "El Campament 3 és a 600 m d’una pista que porta a Cañisaya (4,8 km) i a Curva (10,3 km): evacuació en vehicle."]], "es": [["Antes del Paso de Akamani", "Con tormenta, mala visibilidad, nieve o hielo previstos en los collados: no empezar la subida y quedarse en Incacancha (día de reserva)."], ["Salida por el este", "Si los collados no son practicables, salir por el camino del Akamani hacia Huayrapata y la carretera RN16 (etapas C3 y C4 del plan C): 19,4 km en dos jornadas, sin pasar de 4.060 m."], ["Después del paso", "El Campamento 3 está a 600 m de una pista que lleva a Cañisaya (4,8 km) y a Curva (10,3 km): evacuación en vehículo."]], "en": [["Before the Akamani Pass", "With storms, poor visibility, snow or ice forecast on the passes: do not start the climb and stay in Incacancha (reserve day)."], ["Eastern exit", "If the passes are not practicable, leave by the Akamani trail towards Huayrapata and the RN16 road (plan C stages C3 and C4): 19.4 km over two days, never above 4,060 m."], ["After the pass", "Camp 3 is 600 m from a track that leads to Cañisaya (4.8 km) and Curva (10.3 km): vehicle evacuation."]], "fr": [["Avant le col d’Akamani", "Avec orages, mauvaise visibilité, neige ou glace prévus sur les cols : ne pas commencer la montée et rester à Incacancha (jour de réserve)."], ["Sortie par l’est", "Si les cols ne sont pas praticables, sortir par le chemin de l’Akamani vers Huayrapata et la route RN16 (étapes C3 et C4 du plan C) : 19,4 km en deux jours, sans dépasser 4 060 m."], ["Après le col", "Le camp 3 est à 600 m d’une piste qui mène à Cañisaya (4,8 km) et à Curva (10,3 km) : évacuation en véhicule."]]}, {"day": 10, "ca": [["Cruïlla de Curva (11.10)", "Punt de decisió: si el grup va just de temps o l’arribada a Charazani passaria de les 16.40, la travessa acaba a Curva i es continua en vehicle."], ["Pont del riu", "El 2019 hi havia un pont de formigó a la baixada cap a Charazani. Sense confirmació recent del pont, el final és a Curva."], ["Carretera", "Abans de sortir, comprovar a l’ABC l’estat de la RN16 Charazani–Escoma per al retorn a La Paz."]], "es": [["Cruce de Curva (11:10)", "Punto de decisión: si el grupo va justo de tiempo o la llegada a Charazani pasaría de las 16:40, la travesía termina en Curva y se sigue en vehículo."], ["Puente del río", "En 2019 había un puente de hormigón en la bajada hacia Charazani. Sin confirmación reciente del puente, el final es en Curva."], ["Carretera", "Antes de salir, comprobar en la ABC el estado de la RN16 Charazani–Escoma para el regreso a La Paz."]], "en": [["Curva junction (11:10)", "Decision point: if the group is short of time or arrival in Charazani would be after 16:40, the trek ends at Curva and continues by vehicle."], ["River bridge", "In 2019 there was a concrete bridge on the descent to Charazani. Without recent confirmation of the bridge, the trek ends at Curva."], ["Road", "Before setting off, check with the ABC the state of the RN16 Charazani–Escoma road for the return to La Paz."]], "fr": [["Croisement de Curva (11 h 10)", "Point de décision : si le groupe est juste en temps ou si l’arrivée à Charazani dépasserait 16 h 40, le trek se termine à Curva et continue en véhicule."], ["Pont sur la rivière", "En 2019, il y avait un pont en béton dans la descente vers Charazani. Sans confirmation récente du pont, l’arrivée se fait à Curva."], ["Route", "Avant de partir, vérifier auprès de l’ABC l’état de la RN16 Charazani–Escoma pour le retour à La Paz."]]}], "c": {"totals": {"km": 34.6, "ascent": 2070, "descent": 2440, "max": 4661}, "ca": {"title": "Pla C · Cañisaya – Akamani – Charazani", "intro": "Variant completa que evita el pas Sunchulli, la zona minera de Sunchulli i les Mil Corbes. Quatre jornades, 34,6 km, +2.070/−2.440 m i un punt màxim de 4.661 m. Segueix el camí de l’Akamani, de traçat precolombí, que l’autor del track de 2012 recomana com a alternativa a la ruta clàssica.", "when": ["Abans de sortir de La Paz: si el pas Sunchulli està tancat per neu, si hi ha conflicte a la zona minera, si no hi ha permís de les comunitats o si el reconeixement desaconsella la ruta principal.", "Durant la travessa: des d’Incacancha (dia 8) es pot sortir per les etapes C3 i C4 en lloc de les jornades 9 i 10."], "program": [["1–3", "La Paz: arribada i aclimatació (igual que el programa principal)"], ["4", "La Paz → Curva en vehicle (≈9 h). Allotjament local o tenda a Curva, ≈3.740 m: només 90 m més amunt que La Paz"], ["5–8", "Etapes C1 a C4"], ["9", "Charazani → La Paz. Els dos dies que s’estalvien se sumen als de reserva"], ["", "Aclimatació: La Paz 3.650 m → Curva 3.740 → Cañisaya 3.880 → Incacancha 4.060 → Huayrapata 3.700 → Charazani 3.195. Cap nit puja més de 500 m respecte de l’anterior."]], "source": "Traçat: camí de l’Akamani a OpenStreetMap; altituds del model SRTM (±20 m). Distàncies i desnivells orientatius (±10 %), pendents de reconèixer."}, "es": {"title": "Plan C · Cañisaya – Akamani – Charazani", "intro": "Variante completa que evita el paso Sunchulli, la zona minera de Sunchulli y las Mil Curvas. Cuatro jornadas, 34,6 km, +2.070/−2.440 m y un punto máximo de 4.661 m. Sigue el camino del Akamani, de trazado precolombino, que el autor del track de 2012 recomienda como alternativa a la ruta clásica.", "when": ["Antes de salir de La Paz: si el paso Sunchulli está cerrado por nieve, si hay conflicto en la zona minera, si no hay permiso de las comunidades o si el reconocimiento desaconseja la ruta principal.", "Durante la travesía: desde Incacancha (día 8) se puede salir por las etapas C3 y C4 en lugar de las jornadas 9 y 10."], "program": [["1–3", "La Paz: llegada y aclimatación (igual que el programa principal)"], ["4", "La Paz → Curva en vehículo (≈9 h). Alojamiento local o tienda en Curva, ≈3.740 m: solo 90 m más arriba que La Paz"], ["5–8", "Etapas C1 a C4"], ["9", "Charazani → La Paz. Los dos días que se ahorran se suman a los de reserva"], ["", "Aclimatación: La Paz 3.650 m → Curva 3.740 → Cañisaya 3.880 → Incacancha 4.060 → Huayrapata 3.700 → Charazani 3.195. Ninguna noche sube más de 500 m respecto de la anterior."]], "source": "Trazado: camino del Akamani en OpenStreetMap; altitudes del modelo SRTM (±20 m). Distancias y desniveles orientativos (±10 %), pendientes de reconocer."}, "stages": [{"code": "C1", "day": 5, "km": 5.2, "ascent": 200, "descent": 60, "max": 3910, "hours": "2–3 h", "start": "09.00", "arrival": "11.00–12.00", "night": 3880, "nightLabel": "3.880 m", "ca": {"name": "Curva → Cañisaya", "text": "Sortim de Curva, on hem dormit, i fem una caminada curta per pista i camí entre conreus fins a Cañisaya. Serveix d’aclimatació abans de pujar.", "key": "Jornada curta: caminar a poc a poc, beure i preparar el pas de l’endemà.", "night": "Tenda a Cañisaya, en el lloc acordat amb la comunitat"}, "es": {"name": "Curva → Cañisaya", "text": "Salimos de Curva, donde hemos dormido, y hacemos una caminata corta por pista y camino entre cultivos hasta Cañisaya. Sirve de aclimatación antes de subir.", "key": "Jornada corta: caminar despacio, beber y preparar el paso del día siguiente.", "night": "Tienda en Cañisaya, en el lugar acordado con la comunidad"}, "points": [{"ca": "Curva", "es": "Curva", "ele": 3740, "km": 0, "time": "09.00", "ll": [-15.130012, -69.00002], "en": "Curva", "fr": "Curva"}, {"ca": "Cañisaya", "es": "Cañisaya", "ele": 3880, "km": 5.2, "time": "11.00–12.00", "ll": [-15.090628, -69.01792], "en": "Cañisaya", "fr": "Cañisaya"}], "en": {"name": "Curva → Cañisaya", "text": "We leave Curva, where we slept, and take a short walk on tracks and paths between fields to Cañisaya. It helps acclimatisation before climbing.", "key": "Short day: walk slowly, drink and prepare the next day’s pass.", "night": "Tent in Cañisaya, at the site agreed with the community"}, "fr": {"name": "Curva → Cañisaya", "text": "Nous partons de Curva, où nous avons dormi, et faisons une courte marche par piste et chemin entre les cultures jusqu’à Cañisaya. Elle aide à s’acclimater avant de monter.", "key": "Courte journée : marcher lentement, boire et préparer le col du lendemain.", "night": "Tente à Cañisaya, à l’endroit convenu avec la communauté"}}, {"code": "C2", "day": 6, "km": 10.0, "ascent": 950, "descent": 750, "max": 4661, "hours": "6–8 h", "start": "07.10", "arrival": "13.10–15.10", "night": 4060, "nightLabel": "4.060 m", "ca": {"name": "Cañisaya → Pas d’Akamani → Incacancha", "text": "Pugem pel camí de l’Akamani, de traçat precolombí, passem pel Campament 3 i l’Apacheta de Tambillo i creuem el Pas d’Akamani (4.661 m), el punt més alt del pla C. Baixada a les ruïnes d’Incacancha.", "key": "Hora límit al Pas d’Akamani: 13.10. Si no s’hi és, tornar al Campament 3.", "night": "Tenda a Incacancha"}, "es": {"name": "Cañisaya → Paso de Akamani → Incacancha", "text": "Subimos por el camino del Akamani, de trazado precolombino, pasamos por el Campamento 3 y la Apacheta de Tambillo y cruzamos el Paso de Akamani (4.661 m), el punto más alto del plan C. Bajada a las ruinas de Incacancha.", "key": "Hora límite en el Paso de Akamani: 13:10. Si no se ha llegado, volver al Campamento 3.", "night": "Tienda en Incacancha"}, "points": [{"ca": "Cañisaya", "es": "Cañisaya", "ele": 3880, "km": 0, "time": "07.10", "ll": [-15.090628, -69.01792], "en": "Cañisaya", "fr": "Cañisaya"}, {"ca": "Campament 3", "es": "Campamento 3", "ele": 4171, "km": 5.1, "time": "09.40–10.40", "ll": [-15.073298, -68.998971], "en": "Camp 3", "fr": "Camp 3"}, {"ca": "Apacheta de Tambillo", "es": "Apacheta de Tambillo", "ele": 4523, "km": 6.6, "time": "10.40–11.40", "ll": [-15.065097, -68.993473], "en": "Tambillo apacheta", "fr": "Apacheta de Tambillo"}, {"ca": "Pas d’Akamani", "es": "Paso de Akamani", "ele": 4661, "km": 7.3, "time": "11.10–12.10", "ll": [-15.061215, -68.990457], "en": "Akamani Pass", "fr": "Col d’Akamani"}, {"ca": "Incacancha", "es": "Incacancha", "ele": 4060, "km": 10.0, "time": "13.10–15.10", "ll": [-15.049699, -68.974377], "en": "Incacancha", "fr": "Incacancha"}], "en": {"name": "Cañisaya → Akamani Pass → Incacancha", "text": "We climb the Akamani trail, a pre-Columbian route, pass Camp 3 and the Tambillo apacheta and cross the Akamani Pass (4,661 m), the highest point of plan C. Descent to the ruins of Incacancha.", "key": "Cut-off at the Akamani Pass: 13:10. If not there by then, return to Camp 3.", "night": "Tent in Incacancha"}, "fr": {"name": "Cañisaya → col d’Akamani → Incacancha", "text": "Nous montons par le chemin de l’Akamani, au tracé précolombien, passons par le camp 3 et l’apacheta de Tambillo et franchissons le col d’Akamani (4 661 m), point le plus haut du plan C. Descente aux ruines d’Incacancha.", "key": "Heure limite au col d’Akamani : 13 h 10. Sinon, retour au camp 3.", "night": "Tente à Incacancha"}}, {"code": "C3", "day": 7, "km": 12.1, "ascent": 580, "descent": 950, "max": 4060, "hours": "6–8 h", "start": "07.10", "arrival": "13.10–15.10", "night": 3700, "nightLabel": "3.700 m", "ca": {"name": "Incacancha → Pas Lorisani → Huayrapata", "text": "Seguim el camí de l’Akamani riu avall, passem pel mur inca i el Pas Lorisani i baixem fins al refugi del camí. Última remuntada suau fins a Huayrapata.", "key": "Jornada llarga però sense passos alts. Aigua de fonts laterals, mai del riu principal.", "night": "Tenda a Huayrapata, en el lloc acordat amb la comunitat"}, "es": {"name": "Incacancha → Paso Lorisani → Huayrapata", "text": "Seguimos el camino del Akamani río abajo, pasamos por el muro inca y el Paso Lorisani y bajamos hasta el refugio del camino. Última remontada suave hasta Huayrapata.", "key": "Jornada larga pero sin pasos altos. Agua de fuentes laterales, nunca del río principal.", "night": "Tienda en Huayrapata, en el lugar acordado con la comunidad"}, "points": [{"ca": "Incacancha", "es": "Incacancha", "ele": 4060, "km": 0, "time": "07.10", "ll": [-15.049699, -68.974377], "en": "Incacancha", "fr": "Incacancha"}, {"ca": "Mur inca", "es": "Muro inca", "ele": 3920, "km": 1.4, "time": "07.50–08.10", "ll": [-15.0574, -68.9663], "en": "Inca wall", "fr": "Mur inca"}, {"ca": "Pas Lorisani", "es": "Paso Lorisani", "ele": 3970, "km": 4.0, "time": "09.10–09.40", "ll": [-15.0718, -68.9541], "en": "Lorisani Pass", "fr": "Col Lorisani"}, {"ca": "Refugi del camí de l’Akamani", "es": "Refugio del camino del Akamani", "ele": 3590, "km": 6.1, "time": "10.10–10.40", "ll": [-15.0834, -68.9492], "en": "Akamani trail shelter", "fr": "Refuge du chemin de l’Akamani"}, {"ca": "Huayrapata", "es": "Huayrapata", "ele": 3700, "km": 12.1, "time": "13.10–15.10", "ll": [-15.123098, -68.939598], "en": "Huayrapata", "fr": "Huayrapata"}], "en": {"name": "Incacancha → Lorisani Pass → Huayrapata", "text": "We follow the Akamani trail downstream, past the Inca wall and the Lorisani Pass, and descend to the trail shelter. A last gentle climb leads to Huayrapata.", "key": "A long day but with no high passes. Water from side springs, never from the main river.", "night": "Tent in Huayrapata, at the site agreed with the community"}, "fr": {"name": "Incacancha → col Lorisani → Huayrapata", "text": "Nous suivons le chemin de l’Akamani vers l’aval, passons par le mur inca et le col Lorisani et descendons jusqu’au refuge du chemin. Une dernière remontée douce mène à Huayrapata.", "key": "Longue journée mais sans grands cols. Eau des sources latérales, jamais de la rivière principale.", "night": "Tente à Huayrapata, à l’endroit convenu avec la communauté"}}, {"code": "C4", "day": 8, "km": 7.3, "ascent": 340, "descent": 680, "max": 4030, "hours": "4–5 h", "start": "07.10", "arrival": "11.10–12.10", "night": 3195, "nightLabel": "3.195 m", "ca": {"name": "Huayrapata → Pas de Chatalayo → RN16 → Charazani", "text": "Pugem al Pas de Chatalayo (4.030 m), passem per una antiga mina d’antimoni i baixem fins a la carretera RN16. Trasllat en vehicle a Charazani i tarda a les aigües termals.", "key": "El vehicle espera a la RN16, al tram Charazani–Apolo: comprovar-ne l’estat a l’ABC el dia abans.", "night": "Allotjament local a Charazani"}, "es": {"name": "Huayrapata → Paso de Chatalayo → RN16 → Charazani", "text": "Subimos al Paso de Chatalayo (4.030 m), pasamos por una antigua mina de antimonio y bajamos hasta la carretera RN16. Traslado en vehículo a Charazani y tarde en las aguas termales.", "key": "El vehículo espera en la RN16, en el tramo Charazani–Apolo: comprobar su estado en la ABC el día antes.", "night": "Alojamiento local en Charazani"}, "points": [{"ca": "Huayrapata", "es": "Huayrapata", "ele": 3700, "km": 0, "time": "07.10", "ll": [-15.123098, -68.939598], "en": "Huayrapata", "fr": "Huayrapata"}, {"ca": "Pas de Chatalayo", "es": "Paso de Chatalayo", "ele": 4030, "km": 2.7, "time": "08.40–09.10", "ll": [-15.141, -68.9362], "en": "Chatalayo Pass", "fr": "Col de Chatalayo"}, {"ca": "Antiga mina d’antimoni", "es": "Antigua mina de antimonio", "ele": 3930, "km": 3.1, "time": "09.00–09.30", "ll": [-15.1431, -68.9383], "en": "Old antimony mine", "fr": "Ancienne mine d’antimoine"}, {"ca": "Carretera RN16", "es": "Carretera RN16", "ele": 3370, "km": 7.3, "time": "11.10–12.10", "ll": [-15.168328, -68.939378], "en": "RN16 road", "fr": "Route RN16"}], "en": {"name": "Huayrapata → Chatalayo Pass → RN16 → Charazani", "text": "We climb to the Chatalayo Pass (4,030 m), pass an old antimony mine and descend to the RN16 road. Vehicle transfer to Charazani and an afternoon at the hot springs.", "key": "The vehicle waits on the RN16, on the Charazani–Apolo section: check its state with the ABC the day before.", "night": "Local lodging in Charazani"}, "fr": {"name": "Huayrapata → col de Chatalayo → RN16 → Charazani", "text": "Nous montons au col de Chatalayo (4 030 m), passons par une ancienne mine d’antimoine et descendons jusqu’à la route RN16. Transfert en véhicule à Charazani et après-midi aux sources chaudes.", "key": "Le véhicule attend sur la RN16, tronçon Charazani–Apolo : vérifier son état auprès de l’ABC la veille.", "night": "Hébergement local à Charazani"}}], "en": {"title": "Plan C · Cañisaya – Akamani – Charazani", "intro": "A complete variant that avoids the Sunchulli Pass, the Sunchulli mining area and the Mil Curvas. Four days, 34.6 km, +2,070/−2,440 m and a high point of 4,661 m. It follows the Akamani trail, a pre-Columbian route that the author of the 2012 track presents as an alternative to the classic route.", "when": ["Before leaving La Paz: if the Sunchulli Pass is closed by snow, if there is conflict in the mining area, if the communities do not grant permission or if the reconnaissance advises against the main route.", "During the trek: from Incacancha (day 8) the group can exit by stages C3 and C4 instead of days 9 and 10."], "program": [["1–3", "La Paz: arrival and acclimatisation (same as the main programme)"], ["4", "La Paz → Curva by vehicle (≈9 h). Local lodging or tent in Curva, ≈3,740 m: only 90 m higher than La Paz"], ["5–8", "Stages C1 to C4"], ["9", "Charazani → La Paz. The two days saved are added to the reserve days"], ["", "Acclimatisation: La Paz 3,650 m → Curva 3,740 → Cañisaya 3,880 → Incacancha 4,060 → Huayrapata 3,700 → Charazani 3,195. No night is more than 500 m higher than the previous one."]], "source": "Line: Akamani trail on OpenStreetMap; altitudes from the SRTM model (±20 m). Distances and height gains are indicative (±10%) and must be checked on the ground."}, "fr": {"title": "Plan C · Cañisaya – Akamani – Charazani", "intro": "Variante complète qui évite le col Sunchulli, la zone minière de Sunchulli et les Mil Curvas. Quatre jours, 34,6 km, +2 070/−2 440 m et un point culminant à 4 661 m. Elle suit le chemin de l’Akamani, au tracé précolombien, que l’auteur de la trace de 2012 présente comme alternative à l’itinéraire classique.", "when": ["Avant de quitter La Paz : si le col Sunchulli est fermé par la neige, s’il y a un conflit dans la zone minière, si les communautés ne donnent pas leur autorisation ou si la reconnaissance déconseille l’itinéraire principal.", "Pendant le trek : depuis Incacancha (jour 8), on peut sortir par les étapes C3 et C4 au lieu des jours 9 et 10."], "program": [["1–3", "La Paz : arrivée et acclimatation (comme le programme principal)"], ["4", "La Paz → Curva en véhicule (≈9 h). Hébergement local ou tente à Curva, ≈3 740 m : seulement 90 m plus haut que La Paz"], ["5–8", "Étapes C1 à C4"], ["9", "Charazani → La Paz. Les deux jours économisés s’ajoutent aux jours de réserve"], ["", "Acclimatation : La Paz 3 650 m → Curva 3 740 → Cañisaya 3 880 → Incacancha 4 060 → Huayrapata 3 700 → Charazani 3 195. Aucune nuit ne monte de plus de 500 m par rapport à la précédente."]], "source": "Tracé : chemin de l’Akamani sur OpenStreetMap ; altitudes du modèle SRTM (±20 m). Distances et dénivelés indicatifs (±10 %), à reconnaître sur le terrain."}}, "roads": {"checked": "17/11/2026", "ca": {"title": "Accessos per carretera (ABC)", "items": [["La Paz → Escoma (RN16)", "Xarxa fonamental, asfaltada. L’ABC hi va fer una inspecció el 2026 i hi va acordar treballs de bacheig. Sense talls coneguts en temporada seca."], ["Escoma → Ulla Ulla → Pelechuco", "Camí que no forma part de la xarxa fonamental: no surt als informes diaris de l’ABC. Cal confirmar-ne l’estat amb transportistes de Pelechuco i amb la Governació de La Paz."], ["Escoma → Charazani (RN16)", "Hi ha un projecte de carretera Escoma–Pacobamba amb finançament de la CAF en gestió el 2026: poden aparèixer talls programats per obres."], ["Charazani → Apolo (RN16, tram de Bocamina i Aguas Calientes)", "Punt crític: tallat del 9 al 19 de febrer de 2025; neteja d’esllavissades al gener de 2026; esllavissada i tall al març de 2026; talls de 07.00 a 19.00 per obres d’una alcantarilla a l’agost de 2026 i restriccions per a vehicles mitjans i pesants a l’octubre de 2026. És on s’acaba a peu el pla C."], ["Com i quan consultar-ho", "Informe diari de transitabilitat de l’ABC (transitabilidad.abc.gob.bo) i els seus comptes @carreterasbo, 48 h i 24 h abans de sortir i el dia abans de cada trasllat. El 17/11/2026 el portal tenia el certificat de seguretat caducat i demanava captcha: cal tenir també el telèfon dels transportistes."], ["Si una carretera està tallada", "Esperar amb els dies de reserva. Charazani només té sortida a La Paz per Escoma; si el tram Charazani–Apolo està tallat, el pla C s’acaba a Curva o a Cañisaya en lloc de la RN16."]]}, "es": {"title": "Accesos por carretera (ABC)", "items": [["La Paz → Escoma (RN16)", "Red fundamental, asfaltada. La ABC hizo una inspección en 2026 y acordó trabajos de bacheo. Sin cortes conocidos en temporada seca."], ["Escoma → Ulla Ulla → Pelechuco", "Camino que no forma parte de la red fundamental: no aparece en los informes diarios de la ABC. Hay que confirmar su estado con transportistas de Pelechuco y con la Gobernación de La Paz."], ["Escoma → Charazani (RN16)", "Hay un proyecto de carretera Escoma–Pacobamba con financiación de la CAF en gestión en 2026: pueden aparecer cortes programados por obras."], ["Charazani → Apolo (RN16, tramo de Bocamina y Aguas Calientes)", "Punto crítico: cortado del 9 al 19 de febrero de 2025; limpieza de derrumbes en enero de 2026; derrumbe y corte en marzo de 2026; cortes de 07:00 a 19:00 por obras de una alcantarilla en agosto de 2026 y restricciones para vehículos medianos y pesados en octubre de 2026. Es donde termina a pie el plan C."], ["Cómo y cuándo consultarlo", "Informe diario de transitabilidad de la ABC (transitabilidad.abc.gob.bo) y sus cuentas @carreterasbo, 48 h y 24 h antes de salir y el día antes de cada traslado. El 17/11/2026 el portal tenía el certificado de seguridad caducado y pedía captcha: hay que tener también el teléfono de los transportistas."], ["Si una carretera está cortada", "Esperar con los días de reserva. Charazani solo tiene salida a La Paz por Escoma; si el tramo Charazani–Apolo está cortado, el plan C termina en Curva o en Cañisaya en lugar de la RN16."]]}, "en": {"title": "Road access (ABC)", "items": [["La Paz → Escoma (RN16)", "Main network, paved. The ABC inspected it in 2026 and agreed pothole repairs. No known closures in the dry season."], ["Escoma → Ulla Ulla → Pelechuco", "Road outside the main network: it does not appear in the ABC daily reports. Its state must be confirmed with Pelechuco drivers and the La Paz departmental government."], ["Escoma → Charazani (RN16)", "An Escoma–Pacobamba road project with CAF funding was under way in 2026: scheduled closures for works may appear."], ["Charazani → Apolo (RN16, Bocamina and Aguas Calientes section)", "Critical point: closed from 9 to 19 February 2025; landslide clearing in January 2026; landslide and closure in March 2026; closures from 07:00 to 19:00 for culvert works in August 2026 and restrictions for medium and heavy vehicles in October 2026. This is where plan C ends on foot."], ["How and when to check", "ABC daily road report (transitabilidad.abc.gob.bo) and its @carreterasbo accounts, 48 h and 24 h before leaving and the day before each transfer. On 17/11/2026 the website had an expired security certificate and asked for a captcha: also keep the drivers’ phone numbers."], ["If a road is closed", "Wait using the reserve days. Charazani only connects to La Paz via Escoma; if the Charazani–Apolo section is closed, plan C ends at Curva or Cañisaya instead of the RN16."]]}, "fr": {"title": "Accès routiers (ABC)", "items": [["La Paz → Escoma (RN16)", "Réseau principal, goudronné. L’ABC l’a inspecté en 2026 et a convenu de travaux de reprise. Pas de coupures connues en saison sèche."], ["Escoma → Ulla Ulla → Pelechuco", "Route hors réseau principal : elle n’apparaît pas dans les rapports quotidiens de l’ABC. Son état doit être confirmé auprès des chauffeurs de Pelechuco et du gouvernement départemental de La Paz."], ["Escoma → Charazani (RN16)", "Un projet de route Escoma–Pacobamba financé par la CAF était en cours en 2026 : des coupures programmées pour travaux peuvent apparaître."], ["Charazani → Apolo (RN16, secteur Bocamina et Aguas Calientes)", "Point critique : coupée du 9 au 19 février 2025 ; déblaiement de glissements en janvier 2026 ; glissement et coupure en mars 2026 ; coupures de 07 h à 19 h pour des travaux de buse en août 2026 et restrictions pour les véhicules moyens et lourds en octobre 2026. C’est là que se termine à pied le plan C."], ["Comment et quand vérifier", "Rapport quotidien de praticabilité de l’ABC (transitabilidad.abc.gob.bo) et ses comptes @carreterasbo, 48 h et 24 h avant le départ et la veille de chaque transfert. Le 17/11/2026, le site avait un certificat de sécurité expiré et demandait un captcha : gardez aussi le téléphone des chauffeurs."], ["Si une route est coupée", "Attendre en utilisant les jours de réserve. Charazani n’est relié à La Paz que par Escoma ; si le tronçon Charazani–Apolo est coupé, le plan C se termine à Curva ou à Cañisaya au lieu de la RN16."]]}}, "rules": {"ca": {"title": "Criteris que canvien", "items": [["Aigua", "Tractar-la no n’elimina el mercuri ni altres metalls. A la zona hi ha mineria d’or amb mercuri (rius Sunchulli i Pelechuco). Només s’agafa aigua de fonts per sobre de les mines o confirmades per la comunitat, i se’n porta de reserva a la vall de Sunchulli."], ["Campament 2", "Lluny del campament miner de Sunchully i de la seva aigua, a l’emplaçament més baix de la vall que es confirmi (objectiu ≈4.500 m)."], ["Pistes mineres", "Segons OpenStreetMap, uns 19 dels 53 km del recorregut (un 36 %) van per pistes per a vehicles. Es diu al client amb claredat. A canvi, gairebé tots els trams tenen sortida en vehicle si cal evacuar."], ["Material", "No cal material tècnic per al client. El guia porta microcrampons de reserva només per a plaques de gel aïllades en un sender fàcil. No canvien el límit del TD2: si un pas exigeix grampons, piolet o assegurament, no es creua."], ["Permís de l’àrea protegida", "Permís escrit del SERNAP, tramitat en persona a l’oficina central de La Paz, i registre als campaments de guardaparcs de Pelechuco i Lagunillas. El «passaport» d’àrees protegides de 2024 no és obligatori."]]}, "es": {"title": "Criterios que cambian", "items": [["Agua", "Tratarla no elimina el mercurio ni otros metales. En la zona hay minería de oro con mercurio (ríos Sunchulli y Pelechuco). Solo se coge agua de fuentes por encima de las minas o confirmadas por la comunidad, y se lleva de reserva en el valle de Sunchulli."], ["Campamento 2", "Lejos del campamento minero de Sunchully y de su agua, en el emplazamiento más bajo del valle que se confirme (objetivo ≈4.500 m)."], ["Pistas mineras", "Según OpenStreetMap, unos 19 de los 53 km del recorrido (un 36 %) van por pistas para vehículos. Se le dice al cliente con claridad. A cambio, casi todos los tramos tienen salida en vehículo si hay que evacuar."], ["Material", "No hace falta material técnico para el cliente. El guía lleva microcrampones de reserva solo para placas de hielo aisladas en un sendero fácil. No cambian el límite del TD2: si un paso exige crampones, piolet o aseguramiento, no se cruza."], ["Permiso del área protegida", "Permiso escrito del SERNAP, tramitado en persona en la oficina central de La Paz, y registro en los campamentos de guardaparques de Pelechuco y Lagunillas. El «pasaporte» de áreas protegidas de 2024 no es obligatorio."]]}, "en": {"title": "Criteria that change", "items": [["Water", "Treating it does not remove mercury or other metals. There is gold mining with mercury in the area (Sunchulli and Pelechuco rivers). Water is only taken from springs above the mines or confirmed by the community, and a reserve is carried in the Sunchulli valley."], ["Camp 2", "Away from the Sunchully mining camp and its water, at the lowest site in the valley that can be confirmed (target ≈4,500 m)."], ["Mining tracks", "According to OpenStreetMap, about 19 of the 53 km of the route (36%) follow vehicle tracks. The client is told clearly. In return, almost every section has a vehicle exit for an evacuation."], ["Gear", "No technical gear is needed for the client. The guide carries spare microspikes only for isolated patches of ice on an easy path. They do not change the TD2 limit: if a pass requires crampons, an ice axe or a rope, we do not cross."], ["Protected area permit", "Written permit from SERNAP, obtained in person at the head office in La Paz, and registration at the ranger stations of Pelechuco and Lagunillas. The 2024 protected-areas “passport” is not compulsory."]]}, "fr": {"title": "Critères qui changent", "items": [["Eau", "La traiter n’élimine ni le mercure ni les autres métaux. Il y a des mines d’or utilisant du mercure dans la zone (rivières Sunchulli et Pelechuco). L’eau n’est prise qu’à des sources au-dessus des mines ou confirmées par la communauté, et on en porte une réserve dans la vallée de Sunchulli."], ["Camp 2", "Loin du campement minier de Sunchully et de son eau, sur l’emplacement le plus bas de la vallée qui puisse être confirmé (objectif ≈4 500 m)."], ["Pistes minières", "Selon OpenStreetMap, environ 19 des 53 km de l’itinéraire (36 %) suivent des pistes carrossables. On le dit clairement au client. En contrepartie, presque chaque tronçon a une sortie en véhicule en cas d’évacuation."], ["Matériel", "Aucun matériel technique n’est nécessaire pour le client. Le guide porte des microcrampons de réserve uniquement pour des plaques de glace isolées sur un sentier facile. Ils ne changent pas la limite du TD2 : si un col exige crampons, piolet ou encordement, on ne passe pas."], ["Permis de l’aire protégée", "Permis écrit du SERNAP, obtenu en personne au siège de La Paz, et enregistrement aux postes des gardes de Pelechuco et de Lagunillas. Le « passeport » des aires protégées de 2024 n’est pas obligatoire."]]}}, "escapes": [{"ca": "Hilo Hilo · pista a Pelechuco", "es": "Hilo Hilo · pista a Pelechuco", "ll": [-14.9255, -69.0294], "days": [5, 6, 7], "en": "Hilo Hilo · track to Pelechuco", "fr": "Hilo Hilo · piste vers Pelechuco"}, {"ca": "Sunchully · pista a Sorapata", "es": "Sunchully · pista a Sorapata", "ll": [-15.006, -68.9743], "days": [7, 8], "en": "Sunchully · track to Sorapata", "fr": "Sunchully · piste vers Sorapata"}, {"ca": "Quellwa Cota · pista a Sunchully", "es": "Quellwa Cota · pista a Sunchully", "ll": [-15.0449, -68.9578], "days": [8], "en": "Quellwa Cota · track to Sunchully", "fr": "Quellwa Cota · piste vers Sunchully"}, {"ca": "Cañisaya · pista a Curva", "es": "Cañisaya · pista a Curva", "ll": [-15.0906, -69.0181], "days": [9, 10], "en": "Cañisaya · track to Curva", "fr": "Cañisaya · piste vers Curva"}, {"ca": "Curva · carretera", "es": "Curva · carretera", "ll": [-15.13, -69.0], "days": [10], "en": "Curva · road", "fr": "Curva · route"}]};
